            {!isSingleFile && (
                <button
                    className={`${styles.convertBtn} nodrag`}
                    onClick={handleConvertToCard}
                    title="Convert to Card"
                    onMouseDown={(e) => e.stopPropagation()}
                >
                    <StickyNote size={16} />
