            sel.collapseToEnd();
        }
    }, [editTarget, persistHost]);

    // Wrap the saved selection in a link.
    const applyLink = useCallback((url: string) => {
        const target = editTarget();
        if (!target) return;
        applyLinkElement(target.host, { href: url.trim() }, target.range);
        persistHost(target.host);
