        // under the selection. The other nine hues live on the toolbar.
        if (isCtrl && e.shiftKey && lowerKey === 'h') {
            e.preventDefault();
            // Read off the live selection, not the toolbar's state: this handler
            // is memoized without the format callbacks in its deps.
            highlightSelection(getActiveHighlightFromSelection() ? null : DEFAULT_HIGHLIGHT_HUE);
            return;
        }

        // Ctrl+Shift+↑ - Move block up
        if (isCtrl && e.shiftKey && e.key === 'ArrowUp') {
            e.preventDefault();
            moveBlockUp(id);
            return;
        }

        // Ctrl+Shift+↓ - Move block down
        if (isCtrl && e.shiftKey && e.key === 'ArrowDown') {
            e.preventDefault();
            moveBlockDown(id);
            return;
        }

        // Ctrl+D - Duplicate block
        if (isCtrl && e.key === 'd') {
            e.preventDefault();
            duplicateBlock(id);
            return;
        }

        // Ctrl+/ - Open block menu
        if (isCtrl && e.key === '/') {
            e.preventDefault();
            const blockEl = blockRefs.current[id];
            if (blockEl) {
