                            const i = prev.findIndex(b => b.id === id);
                            if (i === -1) return prev;
                            const nb = [...prev];
                            nb[i] = { ...nb[i], content: textBefore };
                            nb.splice(i + 1, 0, { id: newId, type: 'text', content: textAfter, indent: curIndent });
                            debouncedOnUpdate(nb);
                            return nb;
                        });
                    } else if (isToggleHeader) {
