        return () => {
            document.removeEventListener('copy', onCopy);
            document.removeEventListener('cut', onCut);
        };
    }, [getSelectedBlocks, buildClipboard, setBlocks, debouncedOnUpdate, setSelectedBlockIds, selectedBlockIdsRef]);

    const handleContainerPaste = async (e: React.ClipboardEvent) => {
        // Intercept paste only when not typing inside text inputs, textareas or
        // contenteditables — those have their own per-block paste handler.
        const target = e.target as HTMLElement;
        const isEditable = typeof target?.closest === 'function' && (
            target.tagName === 'INPUT' ||
            target.tagName === 'TEXTAREA' ||
            target.isContentEditable ||
            !!target.closest('[contenteditable]')
        );
        if (isEditable) return;

        let parsedBlocks: Block[] = [];
        const files = e.clipboardData.files;

        if (files && files.length > 0) {
            e.preventDefault();
            parsedBlocks = await parseFiles(files);
        } else {
            const text = e.clipboardData.getData('text/plain')?.trim();
            const html = e.clipboardData.getData('text/html');
            if (!text && !html) return;
            e.preventDefault();
            // Blocks copied from inside the app come back exactly as they were.
            const internal = payloadBlocks(decodePayload(html) ?? { v: 1, kind: 'blocks', blocks: [] });
            parsedBlocks = internal && internal.length > 0 ? internal : parseTextOrHtml(e);
        }

        if (parsedBlocks.length === 0) return;

        /* Land the paste just after whatever is selected rather than at the very
           end of the note. Appending to the end meant a paste could arrive far
           from where the user was working, out of sight. */
        const selectedIds = selectedBlockIdsRef.current;
        setBlocks(prev => {
            let insertAt = prev.length;
            if (selectedIds.size > 0) {
                const lastSelected = prev.reduce((acc, b, i) => (selectedIds.has(b.id) ? i : acc), -1);
                if (lastSelected >= 0) insertAt = lastSelected + 1;
            }
            const newBlocks = [...prev];
            newBlocks.splice(insertAt, 0, ...parsedBlocks);
            debouncedOnUpdate(newBlocks);
            return newBlocks;
        });
        setSelectedBlockIds(new Set());
        setTimeout(() => setFocusId(parsedBlocks[parsedBlocks.length - 1].id), 50);
    };

    return (
        <div
            data-chnk-it-block-editor
            className={`${styles.editor} ${minimal ? styles.minimal : ''}`}
            ref={editorRef}
            tabIndex={-1}
            onBlurCapture={(event) => {
                const nextTarget = event.relatedTarget as Node | null;
                if (!nextTarget || !editorRef.current?.contains(nextTarget)) {
                    flushPendingUpdate();
                }
            }}
            onPaste={handleContainerPaste}
            onDrop={(e) => { handleDrop(e); clearBlockDropIndicators(); }}
            onDragOver={handleEditorDragOver}
            onDragLeave={handleEditorDragLeave}
            onClick={(e) => handleEditorClick(e, wasDraggingRef.current)}
            onPointerDown={(e) => {
                if (e.ctrlKey) {
                    e.stopPropagation();
                }
            }}
            onMouseDown={(e) => {
                // Require Ctrl key for bulk selection
                if (!e.ctrlKey) {
                    return;
                }
                e.stopPropagation(); // Stop React Flow from grabbing the event for canvas selection
                if (e.button === 0 && editorRef.current) {
                    wasDraggingRef.current = false;
                    // Start Selection
                    const rect = editorRef.current.getBoundingClientRect();
                    // Calculate Scale (Robust check for width)
                    const scale = rect.width ? (rect.width / editorRef.current.offsetWidth) : 1;

                    const relativeX = (e.clientX - rect.left) / scale;
                    const relativeY = (e.clientY - rect.top) / scale;

                    setDragSelection({
                        startX: relativeX,
                        startY: relativeY,
                        currentX: relativeX,
                        currentY: relativeY
                    });

                    // Clear previous if not purely additive (Ctrl allows adding, but let's keep it simple: simple click clears)
                    if (!e.shiftKey && !e.ctrlKey) {
                        setSelectedBlockIds(new Set());
                    }
                }
            }}
            onDoubleClick={(e) => {
                const target = e.target as HTMLElement;
                const chip = target.closest(`.${styles.inlinePageChip}`) as HTMLElement;
                if (chip && chip.dataset.nodeId) {
                    e.preventDefault();
                    e.stopPropagation();
                    const nodeId = chip.dataset.nodeId;
                    useStore.getState().navigateToNode(nodeId);
                }
            }}
        >
            {(() => {
                const visibleBlocks: { block: Block, listIndex?: number, hasChildren?: boolean, originalIndex: number }[] = [];

                blocks.forEach((block, index) => {
                    // Calculate List Index for numbered blocks
                    let listIndex = undefined;
                    if (block.type === 'numbered') {
                        let count = index === 0 ? globalStartIndex : 1;
                        if (index > 0) {
                            for (let i = index - 1; i >= 0; i--) {
                                if (blocks[i].type === 'numbered' && (blocks[i].indent || 0) === (block.indent || 0)) {
                                    count++;
                                } else if ((blocks[i].indent || 0) < (block.indent || 0)) {
                                    break;
                                } else if (blocks[i].type !== 'numbered' && (blocks[i].indent || 0) === (block.indent || 0)) {
                                    break; // Reset list if interrupted by another block type at same indent
                                }
                            }
                        }
                        listIndex = count;
                    }

                    // If this block is a toggle, calculate hasChildren
                    let hasChildren = false;
                    if (block.type === 'toggle') {
                        // Check if the next block in the flat list is indented relative to this one
                        if (index < blocks.length - 1 && (blocks[index + 1].indent || 0) > (block.indent || 0)) {
                            hasChildren = true;
                        }
                    }

                    visibleBlocks.push({ block, listIndex, hasChildren, originalIndex: index });
                });

                interface RenderNode {
                    type: 'block' | 'toggle-group';
                    block: Block;
                    listIndex?: number;
                    hasChildren?: boolean;
                    originalIndex: number;
                    children: RenderNode[];
                }

                const buildRenderTree = (blocksList: typeof visibleBlocks): RenderNode[] => {
                    const root: RenderNode[] = [];
                    const stack: { node: RenderNode; indent: number }[] = [];

                    blocksList.forEach(item => {
                        const indent = item.block.indent || 0;

                        // Find the correct parent in the stack
                        while (stack.length > 0 && stack[stack.length - 1].indent >= indent) {
                            stack.pop();
                        }

                        const currentNode: RenderNode = {
                            type: item.block.type === 'toggle' ? 'toggle-group' : 'block',
                            block: item.block,
                            listIndex: item.listIndex,
                            hasChildren: item.hasChildren,
                            originalIndex: item.originalIndex,
                            children: []
                        };

                        if (stack.length > 0) {
                            stack[stack.length - 1].node.children.push(currentNode);
                        } else {
                            root.push(currentNode);
                        }

                        if (item.block.type === 'toggle') {
                            stack.push({ node: currentNode, indent });
                        }
                    });

                    return root;
                };

                const renderNode = (node: RenderNode, parentToggleIndent?: number, forceReadOnly?: boolean, isFirstChildOfToggle?: boolean): React.ReactNode => {
                    const currentReadOnly = readOnly || forceReadOnly;
                    if (node.type === 'block') {
                        return (
                            <React.Fragment key={node.block.id}>
                                <BlockItem
                                    block={node.block}
                                    index={node.listIndex}
                                    hasChildren={node.hasChildren}
                                    useStoredListNumber={useStoredListNumbers}
                                    isSelected={selectedBlockIds.has(node.block.id)}
                                    isFirstChildOfToggle={isFirstChildOfToggle}
                                    readOnly={currentReadOnly}
                                    nodeId={nodeId}
                                    hideBlockHandles={hideBlockHandles}
                                    promoteBlockHandles={promoteBlockHandles}
                                    disableMediaControls={disableMediaControls}
                                    parentToggleIndent={parentToggleIndent}
                                    minimal={minimal}
                                    onUpdateBlock={updateBlock}
                                    onKeyDown={handleKeyDown}
                                    onPaste={handleBlockPaste}
                                    onMoveBlock={handleMoveBlock}
                                    onDragStart={handleDragStartWrapped}
                                    onMenuOpen={handleBlockMenuOpen}
                                    onDeleteBlock={handleDeleteBlock}
                                    onSelectionClick={() => {
                                        if (selectedBlockIds.size > 0) {
                                            setSelectedBlockIds(new Set());
                                        }
                                    }}
                                    onSelectionMouseDown={handleSelectionMouseDown}
                                    onRegisterRef={handleRegisterRef}
                                />
                                {renderBetweenBlocks && node.originalIndex < blocks.length - 1 && renderBetweenBlocks(node.originalIndex)}
                            </React.Fragment>
                        );
                    } else {
                        const showChildren = node.children && node.children.length > 0;
                        const relativeIndent = Math.max(0, (node.block.indent || 0) - (parentToggleIndent || 0));
                        const isCollapsed = node.block.metadata?.isCollapsed;
                        return (
                            <React.Fragment key={node.block.id}>
                                <div
                                    className={styles.toggleGroupContainer}
                                    // Published as a variable, not an inline margin-left: as an
                                    // inline style it beat every stylesheet rule and flattened the
                                    // canvas gutter to 0 on the left (same trap as --block-indent).
                                    style={{ '--toggle-indent': `${relativeIndent * 24}px` } as React.CSSProperties}
                                >
                                    <BlockItem
                                        block={node.block}
                                        index={node.listIndex}
                                        hasChildren={node.hasChildren}
                                        useStoredListNumber={useStoredListNumbers}
                                        isSelected={selectedBlockIds.has(node.block.id)}
                                        readOnly={currentReadOnly}
                                        nodeId={nodeId}
                                        hideBlockHandles={hideBlockHandles}
                                        promoteBlockHandles={promoteBlockHandles}
                                        disableMediaControls={disableMediaControls}
                                        parentToggleIndent={node.block.indent || 0}
                                        minimal={minimal}
                                        onUpdateBlock={updateBlock}
                                        onKeyDown={handleKeyDown}
                                        onPaste={handleBlockPaste}
                                        onMoveBlock={handleMoveBlock}
                                        onDragStart={handleDragStartWrapped}
                                        onMenuOpen={handleBlockMenuOpen}
                                        onDeleteBlock={handleDeleteBlock}
                                        onSelectionClick={() => {
                                            if (selectedBlockIds.size > 0) {
                                                setSelectedBlockIds(new Set());
                                            }
                                        }}
                                        onSelectionMouseDown={handleSelectionMouseDown}
                                        onRegisterRef={handleRegisterRef}
                                    />
                                    {showChildren && !isCollapsed && (
                                        <div className={styles.toggleChildrenContainer}>
                                            {node.children.map((child, i) => renderNode(child, node.block.indent || 0, currentReadOnly, i === 0))}
                                        </div>
                                    )}
                                </div>
                                {renderBetweenBlocks && node.originalIndex < blocks.length - 1 && renderBetweenBlocks(node.originalIndex)}
                            </React.Fragment>
                        );
                    }
                };

                const renderTree = buildRenderTree(visibleBlocks);
                return renderTree.map(node => renderNode(node));
            })()}

            {slashMenuState && (
                <SlashMenu
                    anchorRect={slashMenuState.anchorRect}
                    filter={blocksRef.current.find(b => b.id === slashMenuState.blockId)?.content.substring(1) || ''}
                    onSelect={(type, meta) => convertBlock(undefined, type, meta, '')}
                    onClose={() => {
                        const targetId = slashMenuState.blockId;
                        setSlashMenuState(null);
                        setFocusId(targetId);
                    }}
                    nodeColor={nodeColor}
                    theme={theme}
                />
            )}

            {blockMenuState && (
                <BlockMenu
                    x={blockMenuState.x}
                    y={blockMenuState.y}
                    // blockId={blockMenuState.blockId} // Passed via closure/state to onAction
                    currentType={blocks.find(b => b.id === blockMenuState.blockId)?.type || 'text'}
                    onClose={() => {
                        const targetId = blockMenuState.blockId;
                        setBlockMenuState(prev => {
                            if (prev?.blockId === targetId) {
                                return null;
                            }
                            return prev;
                        });
                    }}
                    onAction={(action, value) => handleBlockMenuAction(blockMenuState.blockId, action, value)}
                />
            )}
            {/* Floating Toolbar */}
            {/* selectionRect goes null the moment the DOM selection collapses,
                which a click on the toolbar itself can do — so a row the user is
                still working in (the link field, the palette) keeps the toolbar
                mounted against the last known rect. */}
            {(selectionRect || ((linkPopoverOpen || colorPopoverOpen) && lastSelectionRect)) && !slashMenuState && !blockMenuState && (
                <FloatingToolbar
                    selectionRect={(selectionRect || lastSelectionRect)!}
                    activeFormats={activeFormats}
                    activeHighlight={activeHighlight}
                    initialLinkUrl={activeLinkUrl}
                    linkOpen={linkPopoverOpen}
                    onLinkOpenChange={(open) => {
                        setLinkPopoverOpen(open);
                        if (open) setColorPopoverOpen(false);   // one row at a time
                    }}
                    colorOpen={colorPopoverOpen}
                    onColorOpenChange={(open) => {
                        setColorPopoverOpen(open);
                        if (open) setLinkPopoverOpen(false);
                    }}
                    onFormat={(format, value) => {
                        if (format === 'createLink') {
                            if (value !== undefined) applyLink(value);
                        } else if (format === 'createPage') {
                            createPageChip();
                        } else if (format === 'highlight') {
                            // No value = clear it; the swatches always send a hue.
                            highlightSelection(isHighlightHue(value) ? value : null);
                        } else {
                            formatSelection(format as InlineFormat);
                        }
                    }}
                />
            )}

            {/* Selection Rect Overlay */}
            {dragSelection && selectedBlockIds.size > 1 && (
                <div
                    className={styles.selectionRect}
                    style={{
                        left: Math.min(dragSelection.startX, dragSelection.currentX),
                        top: Math.min(dragSelection.startY, dragSelection.currentY),
                        width: Math.abs(dragSelection.currentX - dragSelection.startX),
                        height: Math.abs(dragSelection.currentY - dragSelection.startY)
                    }}
                />
            )}

            {/* Selection Counter */}
            {/* Selection Capsule (Dynamic Island) */}
            {selectedBlockIds.size > 1 && selectionIslandPortalId && (() => {
                const portalTarget = document.getElementById(selectionIslandPortalId);
                if (!portalTarget) return null;
                return createPortal(
                    <SelectionCapsule
                        count={selectedBlockIds.size}
                        onClear={() => setSelectedBlockIds(new Set())}
                        onDelete={deleteSelectedBlocks}
                        onCopy={handleCopySelection}
                        onCut={handleCutSelection}
                    />,
                    portalTarget
                );
            })()}

            {/* Fallback for non-portal mode */}
            {selectedBlockIds.size > 1 && !selectionIslandPortalId && (
                <SelectionCapsule
                    count={selectedBlockIds.size}
                    onClear={() => setSelectedBlockIds(new Set())}
                    onDelete={deleteSelectedBlocks}
                    onCopy={handleCopySelection}
                    onCut={handleCutSelection}
                />
            )}
        </div>
    );
});

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
    ExternalLink, 
    Copy, 
    MoreHorizontal, 
    FileText, 
    Tv, 
    Type, 
    RefreshCw, 
    Check, 
    AlertTriangle,
    Edit3
} from '../../components/icons';
import { fetchMetadata, getDomain, getShortUrl } from '../../services/metadataService';
import { FEATURES } from '../../config/featureFlags';
import { OPEN_YOUTUBE_STUDY_EVENT, parseYouTubeUrl, type OpenYouTubeStudyDetail } from '../youtube/youtubeStudy';
import type { Block, BlockMetadata } from './types';
import styles from './LinkBlock.module.css';

interface LinkBlockProps {
    block: Block;
    readOnly?: boolean;
    onChange: (content: string, metadata?: BlockMetadata) => void;
    onKeyDown?: (e: React.KeyboardEvent) => void;
    onPaste?: (e: React.ClipboardEvent) => void;
    domRef?: (el: HTMLDivElement | null) => void;
}

export const LinkBlock: React.FC<LinkBlockProps> = ({
    block,
    readOnly = false,
    onChange,
    onKeyDown,
    domRef
}) => {
    const url = block.content;
    const metadata = block.metadata || {};
    const displayMode = (metadata.displayMode || 'bookmark') as 'bookmark' | 'embed' | 'text';
    const isEmbeddable = metadata.isEmbeddable ?? false;
    const isLoading = metadata.isLoading ?? false;
    const youtube = parseYouTubeUrl(url);
    const canOpenStudy = FEATURES.youtubeStudy && Boolean(youtube);

    const [showMenu, setShowMenu] = useState(false);
    const [copied, setCopied] = useState(false);
    const [isEditingLabel, setIsEditingLabel] = useState(false);
    const [tempLabel, setTempLabel] = useState(metadata.customTitle || metadata.title || getShortUrl(url));
    const containerRef = useRef<HTMLDivElement>(null);
    const menuRef = useRef<HTMLDivElement>(null);

    // 1. Fetch metadata on mount or URL change if not present
    const loadMetadata = useCallback(async (force = false) => {
        if (!url) return;

        // Skip if already loaded and not forcing a reload
        if (!force && metadata.title && !metadata.isLoading) {
            return;
        }

        // Optimistic UI loading state
        onChange(url, {
            ...metadata,
            isLoading: true,
            displayMode // Preserve current mode
        });

        try {
            const data = await fetchMetadata(url);
            onChange(url, {
                ...metadata,
                ...data,
                isLoading: false,
                displayMode: metadata.displayMode || (data.isEmbeddable ? 'embed' : 'bookmark') // Autodetect best default representation
            });
            setTempLabel(metadata.customTitle || data.title || getShortUrl(url));
        } catch (e) {
            console.error('Failed to load metadata in LinkBlock:', e);
            onChange(url, {
                ...metadata,
                isLoading: false,
                error: true
            });
        }
    }, [url, metadata, onChange, displayMode]);

    useEffect(() => {
        // Metadata loading synchronizes this external URL resource. The helper
        // publishes its loading state before awaiting the network response.
        // eslint-disable-next-line react-hooks/set-state-in-effect
        loadMetadata();
    }, [url]);

    // Handle clicking outside the menu to close it
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
                setShowMenu(false);
            }
        };

        if (showMenu) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [showMenu]);

    // Mode toggling
    const handleSwitchMode = useCallback((mode: 'bookmark' | 'embed' | 'text') => {
        onChange(url, {
            ...metadata,
            displayMode: mode
        });
        setShowMenu(false);
    }, [url, metadata, onChange]);

    // Copy URL
    const handleCopy = useCallback((e: React.MouseEvent) => {
        e.stopPropagation();
        e.preventDefault();
        navigator.clipboard.writeText(url);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    }, [url]);

    // Open URL in new window
    const handleOpen = useCallback((e: React.MouseEvent) => {
        e.stopPropagation();
        e.preventDefault();
        window.open(url, '_blank', 'noopener,noreferrer');
    }, [url]);

    const handleOpenStudy = useCallback((e: React.MouseEvent) => {
        e.stopPropagation();
        e.preventDefault();
        if (!youtube) return;
        window.dispatchEvent(new CustomEvent<OpenYouTubeStudyDetail>(OPEN_YOUTUBE_STUDY_EVENT, {
            detail: { url: youtube.canonicalUrl },
        }));
    }, [youtube]);

    // Ref registry
    const handleRef = useCallback((el: HTMLDivElement | null) => {
        if (domRef) domRef(el);
        (containerRef as React.MutableRefObject<HTMLDivElement | null>).current = el;
    }, [domRef]);

    // Text link label change
    const handleSaveLabel = useCallback(() => {
        setIsEditingLabel(false);
        onChange(url, {
            ...metadata,
            customTitle: tempLabel
        });
    }, [url, metadata, tempLabel, onChange]);

    // RENDER: Skeleton Loader
    const renderSkeleton = () => {
        return (
            <div className={styles.skeletonCard}>
                <div className={styles.skeletonInfo}>
                    <div className={`${styles.skeletonTitle} ${styles.shimmer}`} />
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', width: '100%' }}>
                        <div className={`${styles.skeletonDesc} ${styles.shimmer}`} />
                        <div className={`${styles.skeletonDesc2} ${styles.shimmer}`} />
                    </div>
                    <div className={styles.skeletonMeta}>
                        <div className={`${styles.skeletonFavicon} ${styles.shimmer}`} />
                        <div className={`${styles.skeletonDomain} ${styles.shimmer}`} />
                    </div>
                </div>
                <div className={`${styles.skeletonImage} ${styles.shimmer}`} />
            </div>
        );
    };

    // RENDER: Bookmark Card Preview
    const renderBookmark = () => {
        // If metadata is loading and we don't have a title yet, show skeleton
        if (isLoading && !metadata.title) {
            return renderSkeleton();
        }

        const titleText = metadata.title || getShortUrl(url);
        const descText = metadata.description || 'No description available for this link.';
        const domainName = getDomain(url);

        return (
            <div 
                className={styles.bookmarkCard}
                onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    window.open(url, '_blank', 'noopener,noreferrer');
                }}
            >
                <div className={styles.bookmarkInfo}>
                    <div className={styles.bookmarkTitle}>{titleText}</div>
                    <div className={styles.bookmarkDesc}>{descText}</div>
                    <div className={styles.bookmarkMeta}>
                        {metadata.favicon && (
                            <img 
                                src={metadata.favicon} 
                                alt="" 
                                className={styles.bookmarkFavicon}
                                onError={(e) => {
                                    (e.target as HTMLElement).style.display = 'none';
                                }}
                            />
                        )}
                        <span className={styles.bookmarkDomain}>{domainName}</span>
                    </div>
                </div>
                {metadata.image && (
                    <div className={styles.bookmarkImageContainer}>
                        <img 
                            src={metadata.image} 
                            alt="" 
                            className={styles.bookmarkImage}
                            onError={(e) => {
                                (e.target as HTMLElement).style.display = 'none';
                            }}
                        />
                    </div>
                )}
            </div>
        );
    };

    // RENDER: Embedded Iframe View
    const renderEmbed = () => {
        if (!isEmbeddable || !metadata.embedUrl) {
            return (
                <div className={styles.embedFallback}>
                    <AlertTriangle size={24} className={styles.embedFallbackIcon} />
                    <div className={styles.embedFallbackTitle}>Embed Not Supported</div>
                    <div className={styles.embedFallbackText}>
                        This provider ({getDomain(url)}) doesn't support inline embedding, or the URL format is invalid.
                    </div>
                    <button 
                        onClick={() => handleSwitchMode('bookmark')} 
                        className={styles.dropdownItem}
                        style={{ width: 'auto', background: 'rgba(255,255,255,0.05)', padding: '6px 12px', border: '1px solid rgba(255,255,255,0.1)' }}
                    >
                        Switch to Bookmark Preview
                    </button>
                </div>
            );
        }

        const domain = getDomain(url);
        const isPdf = metadata.provider === 'pdf';

        return (
            <div className={styles.embedContainer}>
                <div className={styles.embedHeader}>
                    <div className={styles.embedTitle}>
                        <Tv size={12} />
                        <span>{metadata.title || `Embedded ${metadata.provider || domain}`}</span>
                    </div>
                    {canOpenStudy && (
                        <button
                            type="button"
                            className={styles.studyButton}
                            onClick={handleOpenStudy}
                            title="Open this video in YouTube Study Studio"
                        >
                            <Tv size={13} />
                            Study
                        </button>
                    )}
                </div>
                <div className={`${styles.embedContent} ${isPdf ? styles.pdfContent : ''}`}>
                    <iframe
                        src={metadata.embedUrl}
                        title={metadata.title || "Embedded resource"}
                        className={styles.embedIframe}
                        loading="lazy"
                        sandbox="allow-scripts allow-same-origin allow-presentation allow-forms allow-popups"
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                        allowFullScreen
                    />
                </div>
            </div>
        );
    };

    // RENDER: Simple Text Link
    const renderTextLink = () => {
        const displayText = metadata.customTitle || metadata.title || getShortUrl(url);
        
        return (
            <div className={styles.textLinkContainer} onClick={(e) => e.stopPropagation()}>
                {isEditingLabel ? (
                    <div style={{ display: 'inline-flex', alignItems: 'center', gap: '4px' }}>
                        <input
                            type="text"
                            value={tempLabel}
                            onChange={(e) => setTempLabel(e.target.value)}
                            onKeyDown={(e) => {
                                if (e.key === 'Enter') handleSaveLabel();
                                if (e.key === 'Escape') setIsEditingLabel(false);
                            }}
                            className={styles.textLinkLabel}
                            style={{
                                background: 'var(--input-bg)',
                                border: '1px solid var(--input-border-focus)',
                                borderRadius: 'var(--r-xs)',
                                padding: '2px 6px',
                                color: 'var(--accent-ink)',
                                width: '180px'
                            }}
                            autoFocus
                        />
                        <button onClick={handleSaveLabel} className={styles.controlBtn} style={{ color: 'var(--ok)' }}>
                            <Check size={14} />
                        </button>
                    </div>
                ) : (
                    <span className={styles.textLinkWrapper} onClick={(e) => {
                        e.stopPropagation();
                        handleOpen(e);
                    }} title="Open link">
                        {metadata.favicon && (
                            <img 
                                src={metadata.favicon} 
                                alt="" 
                                className={styles.textLinkIcon} 
                                onError={(e) => {
                                    (e.target as HTMLElement).style.display = 'none';
                                }}
                            />
                        )}
                        <span>{displayText}</span>
                        <ExternalLink size={10} style={{ opacity: 0.6 }} />
                    </span>
                )}
            </div>
        );
    };

    return (
        <div 
            ref={handleRef}
            className={`${styles.container} ${showMenu ? styles.containerHasActiveMenu : ''}`}
            onKeyDown={onKeyDown}
            tabIndex={0}
        >
            {/* Display correct mode */}
            {!url ? (
                <div className={styles.inputContainer} onClick={(e) => e.stopPropagation()}>
                    <div className={styles.inputWrapper}>
                        <ExternalLink size={16} className={styles.inputIcon} />
                        <input
                            type="text"
                            placeholder="Paste a URL or link (e.g. YouTube, Figma, Spotify)..."
                            className={styles.inputField}
                            onKeyDown={(e) => {
                                if (e.key === 'Enter') {
                                    const targetUrl = (e.currentTarget.value || '').trim();
                                    if (targetUrl) {
                                        onChange(targetUrl, {
                                            ...metadata,
                                            isLoading: true,
                                            displayMode: 'bookmark'
                                        });
                                    }
                                }
                            }}
                            autoFocus
                        />
                    </div>
                </div>
            ) : (
                <>
                    {displayMode === 'bookmark' && renderBookmark()}
                    {displayMode === 'embed' && renderEmbed()}
                    {displayMode === 'text' && renderTextLink()}
                </>
            )}

            {/* Hover Floating Actions & Mode Switcher */}
            {!readOnly && (
                <div className={styles.floatingControls}>
                    {canOpenStudy && (
                        <button
                            type="button"
                            onClick={handleOpenStudy}
                            className={styles.controlBtn}
                            title="Open in YouTube Study Studio"
                        >
                            <Tv size={13} />
                        </button>
                    )}
                    <button 
                        onClick={handleOpen} 
                        className={styles.controlBtn} 
                        title="Open in new tab"
                    >
                        <ExternalLink size={13} />
                    </button>
                    <button 
                        onClick={handleCopy} 
                        className={styles.controlBtn} 
                        title={copied ? "Copied!" : "Copy link"}
                    >
                        {copied ? <Check size={13} style={{ color: 'var(--ok)' }} /> : <Copy size={13} />}
                    </button>
                    <button 
                        onClick={() => loadMetadata(true)} 
                        className={`${styles.controlBtn} ${isLoading ? styles.shimmer : ''}`} 
                        title="Refresh metadata"
                        disabled={isLoading}
                    >
                        <RefreshCw size={13} className={isLoading ? 'animate-spin' : ''} />
                    </button>
                    
                    <div style={{ width: '1px', height: '14px', background: 'rgba(255,255,255,0.15)', margin: '0 4px' }} />
                    
                    <button 
                        onClick={() => setShowMenu(!showMenu)} 
                        className={`${styles.controlBtn} ${showMenu ? styles.controlBtnActive : ''}`} 
                        title="Link Display Modes"
                    >
                        <MoreHorizontal size={13} />
                    </button>
                </div>
            )}

            {/* Quick switcher dropdown */}
            {showMenu && (
                <div ref={menuRef} className={styles.dropdownMenu}>
                    <div style={{ padding: '6px 8px', fontSize: '10px', color: 'rgba(255,255,255,0.4)', fontWeight: 'bold' }}>
                        DISPLAY ASPECT
                    </div>
                    
                    <button 
                        onClick={() => handleSwitchMode('bookmark')} 
                        className={`${styles.dropdownItem} ${displayMode === 'bookmark' ? styles.dropdownItemActive : ''}`}
                    >
                        <FileText size={13} />
                        <span>Bookmark Preview</span>
                        {displayMode === 'bookmark' && <Check size={12} style={{ marginLeft: 'auto' }} />}
                    </button>
                    
                    <button 
                        onClick={() => handleSwitchMode('embed')} 
                        className={`${styles.dropdownItem} ${displayMode === 'embed' ? styles.dropdownItemActive : ''}`}
                        disabled={!isEmbeddable}
                        style={!isEmbeddable ? { opacity: 0.4, cursor: 'not-allowed' } : {}}
                        title={!isEmbeddable ? "Provider doesn't support embedding" : ""}
                    >
                        <Tv size={13} />
                        <span>Embedded Frame</span>
                        {displayMode === 'embed' && <Check size={12} style={{ marginLeft: 'auto' }} />}
                    </button>
                    
                    <button 
                        onClick={() => handleSwitchMode('text')} 
                        className={`${styles.dropdownItem} ${displayMode === 'text' ? styles.dropdownItemActive : ''}`}
                    >
                        <Type size={13} />
                        <span>Text Link Pill</span>
                        {displayMode === 'text' && <Check size={12} style={{ marginLeft: 'auto' }} />}
                    </button>

                    <div className={styles.dropdownSeparator} />
                    
                    <button 
                        onClick={() => { setIsEditingLabel(true); setShowMenu(false); }}
                        className={styles.dropdownItem}
                    >
                        <Edit3 size={13} />
                        <span>Rename Label</span>
                    </button>
                </div>
            )}
        </div>
    );
};

