import { useCallback } from 'react';
import type { MutableRefObject } from 'react';
import type { Block, BlockType, BlockMetadata, BlockDropPosition } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { useStore } from '../../../store/useStore';
import { getNodeBlocks } from '../../../types';
import { endBlockDrag } from '../blockDragLock';
import { ingestFiles } from '../../../services/assets';
import { canAbsorbIntoGallery, mergeIntoGallery, claimGalleryItem, GALLERY_DRAG_MIME } from '../galleryTypes';

interface DragAndDropProps {
    blocks: Block[];
    setBlocks: React.Dispatch<React.SetStateAction<Block[]>>;
    debouncedOnUpdate: (newBlocks: Block[]) => void;
    selectedBlockIds: Set<string>;
    nodeId?: string;
    addBlock: (afterId: string, type: BlockType, indent?: number, metadata?: BlockMetadata) => void;
    editorId: string;
    pendingDropTarget?: MutableRefObject<{ blockId: string; position: BlockDropPosition } | null>;
}

export function useBlockDragAndDrop({
    blocks,
    setBlocks,
    debouncedOnUpdate,
    selectedBlockIds,
    pendingDropTarget,
    nodeId,
    addBlock,
    editorId
}: DragAndDropProps) {

    // Helper: Remove blocks from source node (if different from current)
    const removeBlocksFromSource = useCallback((blockIds: string[], sourceNodeId: string | null) => {
        console.log("[useBlockDragAndDrop] removeBlocksFromSource called:", {
            blockIds,
            sourceNodeId,
            currentNodeId: nodeId
        });

        if (sourceNodeId && sourceNodeId !== nodeId) {
            const { nodes, updateNodeData, setNodes } = useStore.getState();
            const sourceNode = nodes.find(n => n.id === sourceNodeId);

            console.log("[useBlockDragAndDrop] Source node found:", !!sourceNode);

            const currentContent = sourceNode ? getNodeBlocks(sourceNode.data) : undefined;
            if (sourceNode && currentContent) {
                const newContent = currentContent.filter((b) => !blockIds.includes(b.id));

                console.log("[useBlockDragAndDrop] Removing blocks from source:", {
                    sourceNodeId,
                    originalCount: currentContent.length,
                    newCount: newContent.length,
                    removedCount: currentContent.length - newContent.length
                });

                updateNodeData(sourceNodeId, { content: newContent });

                // If source node is now empty and is a fused-note, delete it
                if (newContent.length === 0 && sourceNode.type === 'fused-note') {
                    console.log("[useBlockDragAndDrop] Source node is empty, deleting it");
                    setTimeout(() => {
                        setNodes(nds => nds.filter(n => n.id !== sourceNodeId));
                    }, 0);
                }
            }

            // Trigger cleanup events
            if (window.chnkItMultiDragCleanup) {
                window.chnkItMultiDragCleanup();
                delete window.chnkItMultiDragCleanup;
            }
            // Signal SortableBlockWrapper.handleDragEnd that the drop was already handled.
            window.chnkItCrossEditorDropHandled = true;
            endBlockDrag();
            window.dispatchEvent(new CustomEvent('chnk-it-clear-selection'));
        } else {
            console.log("[useBlockDragAndDrop] NOT removing from source - same node or no source");
        }
    }, [nodeId]);

    const handleMoveBlock = useCallback((sourceId: string, targetId: string, position: BlockDropPosition, dataTransfer?: DataTransfer) => {
        console.log("[useBlockDragAndDrop] handleMoveBlock", { sourceId, targetId, position });

        // Check for cross-editor or cross-node move via DataTransfer
        let isCrossEditor = false;
        if (dataTransfer) {
            const sourceEditorId = dataTransfer.getData('application/chnk-it-editor-id');
            if (sourceEditorId && sourceEditorId !== editorId) {
                isCrossEditor = true;
            }
        }

        if (dataTransfer && !isCrossEditor) {
            try {
                const rawData = dataTransfer.getData('application/chnk-it-block-data');
                if (rawData) {
                    const parsed = JSON.parse(rawData);
                    const sourceNodeId = parsed.sourceNodeId;

                    if (sourceNodeId && sourceNodeId !== nodeId) {
                        console.log("[useBlockDragAndDrop] Cross-node move detected in handleMoveBlock", { sourceNodeId, nodeId });

                        let blocksToRemove: string[] = [];
                        if (parsed.blocks) blocksToRemove = parsed.blocks.map((b: { id: string }) => b.id);
                        else if (parsed.block) blocksToRemove = [parsed.block.id];

                        // If parsing failed to get blocks but we have sourceId, use that
                        if (blocksToRemove.length === 0 && sourceId) blocksToRemove = [sourceId];

                        // Execute removal from source
                        removeBlocksFromSource(blocksToRemove, sourceNodeId);
                    }
                }
            } catch (e) {
                console.error("Failed to parse cross-node data in handleMoveBlock", e);
            }
        }

        setBlocks(prev => {
            let blocksToMove: Block[] = [];
            let sourceIds: string[] = [];

            if (dataTransfer) {
                try {
                    const rawData = dataTransfer.getData('application/chnk-it-block-data');
                    if (rawData) {
                        const parsed = JSON.parse(rawData);
                        if (parsed.blocks) {
                            blocksToMove = parsed.blocks;
                            sourceIds = blocksToMove.map(b => b.id);
                        } else if (parsed.block) {
                            blocksToMove = [parsed.block];
                            sourceIds = [parsed.block.id];
                        }
                    }
                } catch (e) { console.error("Failed to parse drop data", e); }
            }

            // Fallback: If no blocks found in dataTransfer, use local lookup
            if (blocksToMove.length === 0) {
                const fromIndex = prev.findIndex(b => b.id === sourceId);
                if (fromIndex !== -1) {
                    blocksToMove = [prev[fromIndex]];
                    sourceIds = [sourceId];
                }
            }

            // SAFETY: Force include the primary sourceId if it's not in the list
            if (sourceId && !sourceIds.includes(sourceId)) {
                sourceIds.push(sourceId);
            }

            if (blocksToMove.length === 0) return prev;

            console.log("[useBlockDragAndDrop] Moving blocks:", {
                sourceIds,
                targetId,
                blocksToMoveCount: blocksToMove.length
            });

            const originalTargetIndex = prev.findIndex(b => b.id === targetId);
            if (originalTargetIndex === -1 && prev.length > 0) {
                console.warn(`Target block ${targetId} not found, appending to end`);
                const newBlocks = prev.filter(b => !sourceIds.includes(b.id));
                newBlocks.push(...blocksToMove);
                return newBlocks;
            }

            /* Dropped INTO a piece of media rather than beside it: the two become
               one board. The target block is replaced in place (keeping its
               position in the document) and the dragged media is consumed.
               `mergeIntoGallery` returning null is the guard — if this pairing
               isn't really a gallery, fall through to ordinary insertion. */
            if (position === 'center' && originalTargetIndex !== -1) {
                const gallery = mergeIntoGallery([prev[originalTargetIndex]], blocksToMove);
                if (gallery) {
                    const merged = prev
                        .filter(b => !sourceIds.includes(b.id))
                        .map(b => (b.id === targetId ? gallery : b));
                    debouncedOnUpdate(merged);

                    claimGalleryItem(sourceIds);
                    if (isCrossEditor && typeof window.chnkItRemoveDraggedBlocks === 'function') {
                        window.chnkItRemoveDraggedBlocks(sourceIds);
                        window.chnkItRemoveDraggedBlocks = null;
                    }
                    return merged;
                }
            }

            let insertIndex = originalTargetIndex;
            if (position === 'bottom') insertIndex += 1;

            let removedBefore = 0;
            for (let i = 0; i < insertIndex; i++) {
                if (sourceIds.includes(prev[i].id)) removedBefore++;
            }

            const finalInsertIndex = insertIndex - removedBefore;
            const newBlocks = prev.filter(b => !sourceIds.includes(b.id));
            
            const targetBlock = originalTargetIndex !== -1 ? prev[originalTargetIndex] : null;
            
            // Notion-like behavior: If dropping on the bottom of an expanded toggle, 
            // make the moved blocks children of that toggle.
            const updatedBlocksToMove = blocksToMove.map(b => {
                if (targetBlock && targetBlock.type === 'toggle' && !targetBlock.metadata?.isCollapsed && position === 'bottom') {
                    // Calculate relative indent: if moving multiple blocks, maintain their relative indentation
                    const baseIndent = blocksToMove[0].indent || 0;
                    const relativeIndent = (b.indent || 0) - baseIndent;
                    return { ...b, indent: (targetBlock.indent || 0) + 1 + relativeIndent };
                }
                return b;
            });

            newBlocks.splice(finalInsertIndex, 0, ...updatedBlocksToMove);
            debouncedOnUpdate(newBlocks);

            /* Dragged out of a gallery and dropped between blocks: the picture is
               a block in this document now, so the board has to let go of it. */
            claimGalleryItem(sourceIds);

            // If it is a cross-editor drop, trigger source removal callback
            if (isCrossEditor && typeof window.chnkItRemoveDraggedBlocks === 'function') {
                window.chnkItRemoveDraggedBlocks(sourceIds);
                window.chnkItRemoveDraggedBlocks = null;
            }

            return newBlocks;
        });

        if (isCrossEditor) {
            // The source editor just dropped the block from its own state, so the drag
            // source element unmounts before `dragend` fires — and a detached element's
            // dragend never reaches SortableBlockWrapper. Run the end-of-drag cleanup
            // here instead, or the drag lock stays raised and blocks all editing.
            window.chnkItCrossEditorDropHandled = true;
            endBlockDrag();
            window.dispatchEvent(new CustomEvent('chnk-it-clear-selection'));
        }
    }, [debouncedOnUpdate, setBlocks, removeBlocksFromSource, nodeId, editorId]);

    const handleBlockDragStart = useCallback((e: React.DragEvent, block: Block) => {
        const isMulti = selectedBlockIds.has(block.id) && selectedBlockIds.size > 1;
        e.dataTransfer.effectAllowed = 'copyMove';
        e.dataTransfer.setData('application/chnk-it-block-id', block.id);
        e.dataTransfer.setData('application/reactflow-block-type', block.type);
        e.dataTransfer.setData('application/chnk-it-editor-id', editorId);

        const blocksToDrag = isMulti
            ? blocks.filter(b => selectedBlockIds.has(b.id))
            : [block];

        /* Announce that this payload could join a board. Drop targets can only
           read `types` during dragover, so this presence flag is what lets a
           media block offer its merge band before the drop commits. */
        if (canAbsorbIntoGallery(blocksToDrag)) {
            e.dataTransfer.setData(GALLERY_DRAG_MIME, '1');
        }

        window.chnkItRemoveDraggedBlocks = (ids: string[]) => {
            console.log("[chnkItRemoveDraggedBlocks] Removing blocks from source:", ids);
            setBlocks(prev => {
                const newBlocks = prev.filter(b => !ids.includes(b.id));
                debouncedOnUpdate(newBlocks);
                return newBlocks;
            });
        };

        e.dataTransfer.setData('application/chnk-it-block-data', JSON.stringify({
            block,
            blocks: blocksToDrag,
            sourceNodeId: nodeId || null
        }));

        // Register global cleanup for multi-block drag operations
        if (isMulti) {
            console.log('Registering multi-block drag cleanup for', blocksToDrag.length, 'blocks');
            window.chnkItMultiDragCleanup = () => {
                console.log('Executing multi-block drag cleanup');
                // Dispatch both events to ensure cleanup
                const event1 = new CustomEvent('chnk-it-clear-selection');
                const event2 = new CustomEvent('chnk-it-multi-drag-clear-selection');
                window.dispatchEvent(event1);
                window.dispatchEvent(event2);
            };
        }
    }, [selectedBlockIds, blocks, nodeId, editorId, debouncedOnUpdate, setBlocks]);

    const handleDrop = useCallback((e: React.DragEvent) => {
        console.log("[BlockEditor.handleDrop] START - Event triggered, nodeId:", nodeId);
        e.preventDefault();
        e.stopPropagation();

        if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
            // One write for the whole drop. The previous per-file FileReader
            // callbacks each rebuilt `blocks` from their own stale closure, so
            // dropping four files reliably kept only the last to finish — and
            // none of them ever met the size limit.
            const dropped = Array.from(e.dataTransfer.files);
            void ingestFiles(dropped).then(({ files: stored }) => {
                if (!stored.length) return;
                const newBlocks: Block[] = stored.map(f => ({
                    id: uuidv4(),
                    type: f.type,
                    content: f.ref,
                    metadata: f.metadata,
                }));
                setBlocks(prev => {
                    const next = [...prev, ...newBlocks];
                    debouncedOnUpdate(next);
                    return next;
                });
            });
            return;
        }

        const type = e.dataTransfer.getData('application/reactflow-block-type') as BlockType;
        if (type) {
            const sourceBlockId = e.dataTransfer.getData('application/chnk-it-block-id');

            // Parse block data to get source info
            let sourceNodeId: string | null = null;
            let blocksFromData: Block[] = [];

            try {
                const rawData = e.dataTransfer.getData('application/chnk-it-block-data');
                if (rawData) {
                    const parsed = JSON.parse(rawData);
                    sourceNodeId = parsed.sourceNodeId || null;
                    if (parsed.blocks) {
                        blocksFromData = parsed.blocks;
                    } else if (parsed.block) {
                        blocksFromData = [parsed.block];
                    }
                }
            } catch (err) { console.error("Failed to parse drop data", err); }

            console.log("[BlockEditor.handleDrop] Parsed data:", {
                type,
                sourceBlockId,
                sourceNodeId,
                currentNodeId: nodeId,
                blocksFromDataCount: blocksFromData.length,
                isCrossNodeDrop: sourceNodeId && sourceNodeId !== nodeId
            });

            if (sourceBlockId) {
                if (blocks.length === 0) {
                    console.log("[BlockEditor.handleDrop] Drop into empty editor");
                    // Drop into empty editor
                    if (blocksFromData.length > 0) {
                        setBlocks(blocksFromData);
                        debouncedOnUpdate(blocksFromData);

                        claimGalleryItem(blocksFromData.map(b => b.id));
                        const sourceEditorId = e.dataTransfer.getData('application/chnk-it-editor-id');
                        if (sourceEditorId && sourceEditorId !== editorId && typeof window.chnkItRemoveDraggedBlocks === 'function') {
                            window.chnkItRemoveDraggedBlocks(blocksFromData.map(b => b.id));
                            window.chnkItRemoveDraggedBlocks = null;
                        } else {
                            // Remove from source node if cross-node drop
                            removeBlocksFromSource(blocksFromData.map(b => b.id), sourceNodeId);
                        }
                    }
                    return;
                }

                // If this is a cross-node drop, handle specially
                if (sourceNodeId && sourceNodeId !== nodeId && blocksFromData.length > 0) {
                    console.log("[BlockEditor.handleDrop] CROSS-NODE DROP - Adding blocks and removing from source");
                    // Add blocks to this node
                    setBlocks(prev => {
                        const newBlocks = [...prev, ...blocksFromData];
                        debouncedOnUpdate(newBlocks);
                        return newBlocks;
                    });

                    // Remove from source node
                    removeBlocksFromSource(blocksFromData.map(b => b.id), sourceNodeId);
                    return;
                }

                // Same-node move (internal reorder) — use container-tracked target if available
                console.log("[BlockEditor.handleDrop] SAME-NODE move (internal reorder)");
                const tracked = pendingDropTarget?.current;
                if (tracked) {
                    handleMoveBlock(sourceBlockId, tracked.blockId, tracked.position, e.dataTransfer);
                } else {
                    const lastId = blocks[blocks.length - 1].id;
                    handleMoveBlock(sourceBlockId, lastId, 'bottom', e.dataTransfer);
                }
                return;
            }

            // External drop (e.g. from menu) - blocks without sourceBlockId
            console.log("[BlockEditor.handleDrop] External drop (no sourceBlockId)");
            if (blocksFromData.length > 0) {
                // If we have full block data, insert it at the end
                setBlocks(prev => {
                    const newBlocks = [...prev, ...blocksFromData];
                    debouncedOnUpdate(newBlocks);
                    return newBlocks;
                });

                claimGalleryItem(blocksFromData.map(b => b.id));
                // Remove from source node if cross-node drop
                removeBlocksFromSource(blocksFromData.map(b => b.id), sourceNodeId);
            } else {
                // Fallback to type-based creation (new block from menu)
                let metadata = undefined;
                try {
                    const metaJson = e.dataTransfer.getData('application/chnk-it-block-metadata');
                    if (metaJson) metadata = JSON.parse(metaJson);
                } catch (err) { console.error("Failed to parse drop metadata", err); }

                const lastId = blocks.length > 0 ? blocks[blocks.length - 1].id : '0';
                // pass 0 as default indent
                addBlock(lastId, type, 0, metadata);
            }
        } else {
            console.log("[BlockEditor.handleDrop] No type in dataTransfer - ignoring");
        }
    }, [blocks, addBlock, handleMoveBlock, debouncedOnUpdate, setBlocks, nodeId, removeBlocksFromSource, editorId, pendingDropTarget]);

    const handleDragOver = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        e.dataTransfer.dropEffect = 'copy';
    }, []);

    return {
        handleMoveBlock,
        handleBlockDragStart,
        handleDrop,
        handleDragOver
    };
}

import { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import type { Block } from '../types';
import { throttle } from '../../../utils/throttle';

interface SelectionProps {
    editorRef: React.RefObject<HTMLDivElement | null>;
    blocks: Block[];
    blocksRef: React.MutableRefObject<Block[]>; // Added blocksRef
    blockRefs: React.MutableRefObject<{ [key: string]: HTMLElement | null }>;
}

export function useBlockSelection({ editorRef, blocks, blocksRef, blockRefs }: SelectionProps) {
    const [selectedBlockIds, setSelectedBlockIds] = useState<Set<string>>(new Set());
    const [dragSelection, setDragSelection] = useState<{ startX: number, startY: number, currentX: number, currentY: number } | null>(null);
    const [mouseDownBlock, setMouseDownBlock] = useState<{ id: string, startX: number, startY: number, initialRect: DOMRect, isInteractive: boolean } | null>(null);
    const [selectionRect, setSelectionRect] = useState<DOMRect | null>(null);
    const wasDraggingRef = useRef(false);

    // Use refs to avoid re-renders on frequent updates
    const selectionRectRef = useRef<DOMRect | null>(null);
    const dragSelectionRef = useRef(dragSelection);

    const selectedBlockIdsRef = useRef(selectedBlockIds);
    useEffect(() => {
        selectedBlockIdsRef.current = selectedBlockIds;
    }, [selectedBlockIds]);

    // Keep drag selection ref in sync
    useEffect(() => {
        dragSelectionRef.current = dragSelection;
    }, [dragSelection]);

    // Throttled selection calculation to improve performance
    const throttledCalculateSelection = useMemo(
        () => throttle((dragSel: { startX: number, startY: number, currentX: number, currentY: number }, editorEl: HTMLDivElement, blockElements: typeof blockRefs.current, currentBlocks: Block[]) => {
            const left = Math.min(dragSel.startX, dragSel.currentX);
            const top = Math.min(dragSel.startY, dragSel.currentY);
            const width = Math.abs(dragSel.currentX - dragSel.startX);
            const height = Math.abs(dragSel.currentY - dragSel.startY);
            const selectionBox = { left, top, right: left + width, bottom: top + height };

            const newSelected = new Set<string>();
            const editorRect = editorEl.getBoundingClientRect();
            const computedStyle = getComputedStyle(editorEl);
            const transform = computedStyle.transform || 'matrix(1, 0, 0, 1, 0, 0)';
            const scaleMatch = transform.match(/matrix\(([^)]+)\)/);
            const scale = scaleMatch ?
                parseFloat(scaleMatch[1].split(',')[3] || '1') :
                (editorRect.width && editorEl.offsetWidth ?
                    editorRect.width / editorEl.offsetWidth : 1);

            currentBlocks.forEach(block => {
                const el = blockElements[block.id];
                if (el) {
                    const blockRect = el.getBoundingClientRect();
                    const blockRelative = {
                        left: (blockRect.left - editorRect.left) / scale,
                        top: (blockRect.top - editorRect.top) / scale,
                        right: (blockRect.right - editorRect.left) / scale,
                        bottom: (blockRect.bottom - editorRect.top) / scale
                    };

                    if (
                        blockRelative.left < selectionBox.right &&
                        blockRelative.right > selectionBox.left &&
                        blockRelative.top < selectionBox.bottom &&
                        blockRelative.bottom > selectionBox.top
                    ) {
                        newSelected.add(block.id);
                    }
                }
            });

            if (newSelected.size > 0) {
                setSelectedBlockIds(newSelected);
            }
        }, 32), // ~30fps instead of 60fps for less CPU usage
        [setSelectedBlockIds]
    );

    // Selection Logic Effect - optimized to avoid frequent state updates
    useEffect(() => {
        if (!dragSelection && !mouseDownBlock) return;

        const handleGlobalMouseMove = (e: MouseEvent) => {
            if (document.body.classList.contains('chnk-it-block-dragging') || window.chnkItBlockDragging) {
                return;
            }
            if (!editorRef.current) return;
            const editorRect = editorRef.current.getBoundingClientRect();

            if (mouseDownBlock && !dragSelectionRef.current) {
                const { initialRect } = mouseDownBlock;
                const isOutside =
                    e.clientY < initialRect.top ||
                    e.clientY > initialRect.bottom ||
                    e.clientX < initialRect.left - 50 ||
                    e.clientX > initialRect.right + 50;

                if (isOutside) {
                    window.getSelection()?.removeAllRanges();
                    if (editorRef.current) {
                        // A tall editor would otherwise be scrolled to its top.
                        editorRef.current.focus({ preventScroll: true });
                    }

                    const computedStyle = editorRef.current ? getComputedStyle(editorRef.current) : null;
                    const transform = computedStyle?.transform || 'matrix(1, 0, 0, 1, 0, 0)';
                    const scaleMatch = transform.match(/matrix\(([^)]+)\)/);
                    const scale = scaleMatch ?
                        parseFloat(scaleMatch[1].split(',')[3] || '1') :
                        (editorRect.width && editorRef.current?.offsetWidth ?
                            editorRect.width / editorRef.current.offsetWidth : 1);
                    const relX = (mouseDownBlock.startX - editorRect.left) / scale;
                    const relY = (mouseDownBlock.startY - editorRect.top) / scale;
                    const currentRelX = (e.clientX - editorRect.left) / scale;
                    const currentRelY = (e.clientY - editorRect.top) / scale;

                    setDragSelection({
                        startX: relX,
                        startY: relY,
                        currentX: currentRelX,
                        currentY: currentRelY
                    });
                    setSelectedBlockIds(new Set([mouseDownBlock.id]));
                    wasDraggingRef.current = true;
                    return;
                }
            }

            if (dragSelectionRef.current) {
                const computedStyle = editorRef.current ? getComputedStyle(editorRef.current) : null;
                const transform = computedStyle?.transform || 'matrix(1, 0, 0, 1, 0, 0)';
                const scaleMatch = transform.match(/matrix\(([^)]+)\)/);
                const scale = scaleMatch ?
                    parseFloat(scaleMatch[1].split(',')[3] || '1') :
                    (editorRect.width && editorRef.current?.offsetWidth ?
                        editorRect.width / editorRef.current.offsetWidth : 1);
                const cx = (e.clientX - editorRect.left) / scale;
                const cy = (e.clientY - editorRect.top) / scale;

                if (!wasDraggingRef.current && (Math.abs(cx - dragSelectionRef.current.startX) > 5 || Math.abs(cy - dragSelectionRef.current.startY) > 5)) {
                    wasDraggingRef.current = true;
                }

                setDragSelection(prev => prev ? {
                    ...prev,
                    currentX: cx,
                    currentY: cy
                } : null);
            }
        };

        const handleGlobalMouseUp = (e: MouseEvent) => {
            if (document.body.classList.contains('chnk-it-block-dragging') || window.chnkItBlockDragging) {
                setDragSelection(null);
                setMouseDownBlock(null);
                setTimeout(() => { wasDraggingRef.current = false; }, 0);
                return;
            }

            if (!wasDraggingRef.current && mouseDownBlock) {
                if (!e.shiftKey && !e.ctrlKey) {
                    if (mouseDownBlock.isInteractive) {
                        if (selectedBlockIdsRef.current.size > 0) setSelectedBlockIds(new Set());
                    } else {
                        if (selectedBlockIdsRef.current.size !== 1 || !selectedBlockIdsRef.current.has(mouseDownBlock.id)) {
                            setSelectedBlockIds(new Set([mouseDownBlock.id]));
                        }
                    }
                }
            }

            setDragSelection(null);
            setMouseDownBlock(null);
            setTimeout(() => { wasDraggingRef.current = false; }, 0);
        };

        if (dragSelection && editorRef.current) {
            throttledCalculateSelection(dragSelection, editorRef.current, blockRefs.current, blocks);
        }

        document.addEventListener('mousemove', handleGlobalMouseMove);
        document.addEventListener('mouseup', handleGlobalMouseUp);
        return () => {
            document.removeEventListener('mousemove', handleGlobalMouseMove);
            document.removeEventListener('mouseup', handleGlobalMouseUp);
        };
    }, [dragSelection, blocks, mouseDownBlock, editorRef, blockRefs, throttledCalculateSelection]);

    // Clear selection when clicking outside - use ref to avoid re-registering
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (!editorRef.current) return;
            const target = e.target as HTMLElement;
            if (editorRef.current.contains(target)) return;

            // Improved portals handling
            if (target.closest('[data-portal="true"]') ||
                target.closest('[data-radix-popper-content-wrapper]') ||
                target.closest('[role="dialog"]') ||
                target.closest('[role="menu"]') ||
                target.closest('.block-menu') ||
                target.closest('.modal') ||
                target.closest('.popover') ||
                target.closest('.dropdown') ||
                target.closest('.fullscreen-modal') ||
                target.closest('.center-modal')) return;

            if (selectedBlockIdsRef.current.size > 0) {
                setTimeout(() => {
                    setSelectedBlockIds(new Set());
                }, 0);
            }
        };

        document.addEventListener('mousedown', handleClickOutside, { capture: true });
        return () => document.removeEventListener('mousedown', handleClickOutside, { capture: true });
    }, [editorRef]); // Removed selectedBlockIds.size - use ref instead

    // Throttled selection change handler for floating toolbar
    useEffect(() => {
        const throttledSelectionChange = throttle(() => {
            const selection = window.getSelection();
            if (!selection || selection.isCollapsed || selection.rangeCount === 0) {
                if (selectionRectRef.current !== null) {
                    selectionRectRef.current = null;
                    setSelectionRect(null);
                }
                return;
            }

            const range = selection.getRangeAt(0);
            if (editorRef.current && editorRef.current.contains(range.commonAncestorContainer)) {
                const rect = range.getBoundingClientRect();
                if (rect.width > 2) {
                    // Only update state if rect changed significantly
                    const prev = selectionRectRef.current;
                    if (!prev || Math.abs(prev.x - rect.x) > 5 || Math.abs(prev.y - rect.y) > 5 || Math.abs(prev.width - rect.width) > 5) {
                        selectionRectRef.current = rect;
                        setSelectionRect(rect);
                    }
                } else if (selectionRectRef.current !== null) {
                    selectionRectRef.current = null;
                    setSelectionRect(null);
                }
            } else if (selectionRectRef.current !== null) {
                selectionRectRef.current = null;
                setSelectionRect(null);
            }
        }, 100);
        document.addEventListener('selectionchange', throttledSelectionChange);
        return () => document.removeEventListener('selectionchange', throttledSelectionChange);
    }, [editorRef]);

    const handleSelectionMouseDown = useCallback((e: React.MouseEvent, id: string) => {
        if (e.shiftKey && selectedBlockIdsRef.current.size > 0) {
            const lastSelectedId = Array.from(selectedBlockIdsRef.current).pop();
            if (lastSelectedId) {
                const startIdx = blocksRef.current.findIndex(b => b.id === lastSelectedId);
                const endIdx = blocksRef.current.findIndex(b => b.id === id);
                if (startIdx !== -1 && endIdx !== -1) {
                    e.preventDefault();
                    const min = Math.min(startIdx, endIdx);
                    const max = Math.max(startIdx, endIdx);
                    const rangeIds = blocksRef.current.slice(min, max + 1).map(b => b.id);
                    setSelectedBlockIds(new Set(rangeIds));
                    return;
                }
            }
        }

        if (e.button === 0) {
            if (e.ctrlKey) {
                // Allow event to bubble up to BlockEditor to initiate bulk selection
                return;
            }
            
            const targetEl = e.target as HTMLElement;
            if (
                targetEl.closest('[class*="dragHandle"]') || 
                targetEl.closest('.custom-drag-handle') ||
                targetEl.closest('[draggable="true"]')
            ) {
                return;
            }
            
            const target = e.currentTarget as HTMLElement;
            const rect = target.getBoundingClientRect();
            setMouseDownBlock({
                id: id,
                startX: e.clientX,
                startY: e.clientY,
                initialRect: rect,
                isInteractive: false
            });
            e.stopPropagation();
        }
    }, [blocksRef]);

    return {
        selectedBlockIds,
        setSelectedBlockIds,
        dragSelection,
        setDragSelection,
        mouseDownBlock,
        setMouseDownBlock,
        selectionRect,
        wasDraggingRef,
        handleSelectionMouseDown,
        selectedBlockIdsRef
    };
}

import { useState, useCallback, useRef, useLayoutEffect } from 'react';
import type { Block, BlockType, BlockMetadata } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { createGalleryMetadata, getGalleryItems, isGalleryMember } from '../galleryTypes';

interface SlashCommandProps {
    editorRef: React.RefObject<HTMLDivElement | null>;
    blocks: Block[];
    blocksRef: React.MutableRefObject<Block[]>; // Added blocksRef
    setBlocks: React.Dispatch<React.SetStateAction<Block[]>>;
    debouncedOnUpdate: (newBlocks: Block[]) => void;
    setFocusId: (id: string | null) => void;
    nodeId?: string;
}

export function useSlashCommand({
    editorRef,
    blocksRef,
    setBlocks,
    debouncedOnUpdate,
    setFocusId,
    nodeId
}: SlashCommandProps) {
    const [slashMenuState, setSlashMenuState] = useState<{ anchorRect: DOMRect | { top: number; left: number; bottom: number }, blockId: string } | null>(null);
    const slashMenuStateRef = useRef(slashMenuState);

    // Sync ref
    useLayoutEffect(() => { slashMenuStateRef.current = slashMenuState; }, [slashMenuState]);

    const convertBlock = useCallback((id: string | undefined, type: BlockType, metadata?: BlockMetadata, content?: string) => {
        const targetId = id || (slashMenuStateRef.current ? slashMenuStateRef.current.blockId : null);
        if (!targetId) return;

        // A divider has no editable content, so it never registers a focusable
        // DOM ref. Converting a block to one used to leave focus with nowhere
        // to go — the user's next keystrokes were silently dropped. Give it a
        // fresh empty block to type into instead, same as pressing Enter would.
        // Decided up front (not inside the setBlocks updater below) because
        // that updater isn't guaranteed to have run yet by the time this
        // function returns — reading a value it assigned from here raced and
        // silently used the divider's own id instead.
        let trailingTextBlockId: string | null = null;
        {
            const current = blocksRef.current;
            const index = current.findIndex(b => b.id === targetId);
            const next = index !== -1 ? current[index + 1] : undefined;
            if (next && next.type === 'text' && !next.content) {
                trailingTextBlockId = next.id;
            } else if (type === 'divider') {
                trailingTextBlockId = uuidv4();
            }
        }

        setBlocks(prev => {
            const index = prev.findIndex(b => b.id === targetId);
            if (index === -1) return prev;

            const updated = [...prev];
            const currentBlock = updated[index];

            let finalContent = content;
            if (content === '') {
                // Parse out the text following the first slash command word
                // e.g. "/h1 Introduction" -> matches "/h1" + spaces, captures "Introduction"
                const match = currentBlock.content.match(/^\/[a-zA-Z0-9]*\s*(.*)/);
                finalContent = match ? match[1] : '';
            } else if (content === undefined) {
                finalContent = currentBlock.content;
            }

            /* Turning a block into a gallery. A picture converts into a board of
               one rather than being thrown away, and the board's `content` is its
               TITLE — so a media block's content (a data URL) must never carry
               over into it, which converting from the block menu would otherwise
               do. Only text becomes a title. */
            const wasGallery = currentBlock.type === 'gallery';
            const wasMedia = isGalleryMember(currentBlock) && !wasGallery;
            const galleryItems = wasGallery
                ? getGalleryItems(currentBlock)
                : (wasMedia && currentBlock.content?.trim() ? [{ ...currentBlock, id: uuidv4() }] : []);
            const galleryTitle = wasGallery ? currentBlock.content : (wasMedia ? '' : (finalContent || ''));

            updated[index] = {
                ...currentBlock,
                type,
                content: type === 'gallery' ? galleryTitle : (finalContent || ''),
                metadata: type === 'columns' ? {
                    columns: Array.from({ length: metadata?.count || 2 }).map(() => ({
                        id: uuidv4(),
                        content: [{ id: uuidv4(), type: 'text', content: '' }]
                    }))
                } : type === 'gallery' ? createGalleryMetadata(galleryItems)
                : (metadata !== undefined ? { ...currentBlock.metadata, ...metadata } : currentBlock.metadata)
            };

            // Converting a toggle to a non-toggle: outdent its nested children by one level so
            // they don't end up orphaned (indented with no parent toggle). Mirrors convertSelectedBlocks.
            if (currentBlock.type === 'toggle' && type !== 'toggle') {
                const targetIndent = currentBlock.indent || 0;
                let j = index + 1;
                while (j < updated.length) {
                    const childIndent = updated[j].indent || 0;
                    if (childIndent > targetIndent) {
                        updated[j] = { ...updated[j], indent: Math.max(0, childIndent - 1) };
                        j++;
                    } else {
                        break;
                    }
                }
            }

            if (type === 'divider' && trailingTextBlockId && !updated.some(b => b.id === trailingTextBlockId)) {
                updated.splice(index + 1, 0, { id: trailingTextBlockId, type: 'text', content: '', indent: currentBlock.indent || 0 });
            }

            debouncedOnUpdate(updated);
            return updated;
        });

        // Auto-split logic removed per user request for better document formatting
        // if (['heading1', 'heading2', 'heading3', 'toggle', 'divider'].includes(type)) {
        //     if (nodeId) {
        //         const index = blocksRef.current.findIndex(b => b.id === targetId);
        //         if (index > 0) {
        //             useStore.getState().splitNode(nodeId, targetId, blocksRef.current);
        //         }
        //     }
        // }

        setFocusId(trailingTextBlockId || targetId);
        setSlashMenuState(null);
    }, [debouncedOnUpdate, nodeId, setBlocks, setFocusId, blocksRef]); // Removed blocks from dependency

    const handleSlashOpen = useCallback((id: string) => {
        const selection = window.getSelection();
        if (selection && selection.rangeCount > 0 && editorRef.current) {
            const range = selection.getRangeAt(0);
            const rect = range.getBoundingClientRect();
            setSlashMenuState({
                anchorRect: { top: rect.top, left: rect.left, bottom: rect.bottom, right: rect.right },
                blockId: id
            });
        }
    }, [editorRef]);

    return {
        slashMenuState,
        setSlashMenuState,
        slashMenuStateRef,
        convertBlock,
        handleSlashOpen
    };
}

import { SearchResults } from './SearchResults';
import {
    Plus,
    LayoutGrid,

    Search,
    X,
    Filter,
    Tag,
    Calendar,
    Flag,
    CheckCircle,
    Sparkles,
    LayoutTemplate,
    KanbanSquare,
    Square,
    RectangleHorizontal,
    File,
    AppWindow,
    Folder
} from '../../components/icons';
import { useState, useMemo, useEffect, useRef, useCallback } from 'react';
import { motion, AnimatePresence, type Variants } from 'motion/react';
import { useReactFlow } from '@xyflow/react';
import { v4 as uuidv4 } from 'uuid';
import { useStore } from '../../store/useStore';
import { getNodeBlocks } from '../../types';
import type { AppState } from '../../store/types';
import styles from './BottomMenu.module.css';
import { MENU_ITEMS } from '../editor/menuConstants';
import { isMediaType } from '../editor/mediaTypes';
import { createGalleryMetadata, GALLERY_NODE_WIDTH } from '../editor/galleryTypes';
import { findNonOverlappingPosition } from '../../utils/findNonOverlappingPosition';
import { MIN_EXPANDED_SIZE } from '../../config/layout';
import { FEATURES } from '../../config/featureFlags';
import {
    KANBAN_CALENDAR_WIDTH,
    KANBAN_DEFAULT_HEIGHT,
    KANBAN_DEFAULT_WIDTH,
} from '../kanban/kanbanTypes';
import { parseSearchQuery } from './searchUtils';
import { MultiSelectionToolbar } from './MultiSelectionToolbar';
import { EdgeEditingToolbar } from './EdgeEditingToolbar';
import { TEMPLATES } from '../templates/templateDefinitions';
import { TemplatePreviewModal } from '../templates/TemplatePreviewModal';
import { FloatingActionButton } from '../../components/ui/Button';

/**
 * Which hover menu is open, if any.
 *
 * Named once rather than spelled out at each of the places that used to carry
 * the union: the state and `openMenu` each had their own copy, and a new id
 * added to one but not the other only surfaces under `tsc -b`.
 */
type MenuId = 'views' | 'blocks' | 'templates' | 'addNoteModes' | 'boardViews' | null;

/* Selection is intentionally isolated from BottomMenu. The menu is a large
   command surface; subscribing it to selection made every click reconcile the
   entire rail before the browser could paint the selected card. */
function NodeSelectionToolbarLayer({ suspended }: { suspended: boolean }) {
    const hasSelection = useStore(s => s.selectedCanvasNodeIds.size > 0);
    const isActive = hasSelection && !suspended;

    return (
        <div
            className={`${styles.flyout} ${styles.selectionIsland} ${styles.contextualToolbar} ${isActive ? styles.contextualToolbarActive : ''}`}
            data-selection-toolbar="true"
            aria-hidden={!isActive}
        >
            <MultiSelectionToolbar isActive={isActive} />
        </div>
    );
}

export function BottomMenu() {
    // Atomic Selectors
    const addNode = useStore(s => s.addNode);
    const centerPanelId = useStore(s => s.centerPanelId);
    const fullscreenId = useStore(s => s.fullscreenId);
    const currentParentId = useStore(s => s.currentParentId);
    const updateNodeData = useStore(s => s.updateNodeData);
    const hasSelectedEdges = useStore(s => Boolean(s.selectedEdgeId) || s.selectedEdgeIds.size > 0);
    /* A node side peek hides the menu outright (see hasNodeSidePeekOpen). The
       other panels — metadata, contents, shortcuts, AI — need no signal here at
       all: they take their width out of `.canvasFrame`, and the menu is centred
       inside that frame, so it re-centres on its own. */
    const rightSidePanelId = useStore(s => s.rightSidePanelId);
    const leftSidePanelId = useStore(s => s.leftSidePanelId);
    const isAIPanelOpen = useStore(s => s.isAIPanelOpen);
    const openAIPanel = useStore(s => s.openAIPanel);
    const toggleAIPanel = useStore(s => s.toggleAIPanel);
    const setAIImageMode = useStore(s => s.setAIImageMode);

    const { screenToFlowPosition, getViewport, setCenter } = useReactFlow();
    const [isSearchMode, setIsSearchMode] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [showFilters, setShowFilters] = useState(false);
    const [activeMenu, setActiveMenu] = useState<MenuId>(null);
    const [hoveredTemplateId, setHoveredTemplateId] = useState<string | null>(null);
    const hoverTimeoutRef = useRef<number | null>(null);
    const [highlightedIndex, setHighlightedIndex] = useState<number | null>(null);
    const menuRef = useRef<HTMLDivElement>(null);
    const handleAddNoteRef = useRef<() => void>(() => {});

    // Hide templates that depend on a beta-deferred surface (e.g. Kanban) so a
    // disabled feature can't leak back in through a template drop.
    const templates = useMemo(
        () => TEMPLATES,
        []
    );

    // Compute the hovered template's preview once. getPreviewData() mints fresh
    // node ids on every call, so calling it separately for nodes and edges made
    // the edges reference ids that no longer existed — they never rendered.
    const hoveredPreview = useMemo(
        () => templates.find(t => t.id === hoveredTemplateId)?.getPreviewData() ?? null,
        [hoveredTemplateId, templates]
    );
    const hoveredTemplate = useMemo(
        () => templates.find(t => t.id === hoveredTemplateId) ?? null,
        [hoveredTemplateId, templates]
    );

    // Reset the highlighted item when the open menu changes. Adjusted during
    // render rather than in an effect: an effect would paint the old highlight
    // for a frame first, and re-entering render is the cheaper of the two.
    const [prevMenu, setPrevMenu] = useState(activeMenu);
    if (prevMenu !== activeMenu) {
        setPrevMenu(activeMenu);
        setHighlightedIndex(activeMenu ? 0 : null);
    }

    // Click-away listener to dismiss active menus and modes when clicking outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setActiveMenu(null);
                if (isSearchMode) {
                    setIsSearchMode(false);
                    setShowFilters(false);
                }
            }
        };

        if (activeMenu || isSearchMode) {
            document.addEventListener('mousedown', handleClickOutside, true);
        }
        return () => {
            document.removeEventListener('mousedown', handleClickOutside, true);
        };
    }, [activeMenu, isSearchMode]);

    // A flyout and a rail popover would otherwise stack on top of each other:
    // the rail stays mounted while search is open, so opening one surface has to
    // dismiss the other explicitly — hence this pair.
    const openSearch = useCallback(() => {
        setActiveMenu(null);
        setIsSearchMode(true);
    }, []);

    // Opening a rail popover closes whatever is in the flyout lane, so only one
    // surface is ever attached to the rail.
    const openMenu = useCallback((menu: MenuId) => {
        if (menu) {
            setIsSearchMode(false);
            setShowFilters(false);
        }
        setActiveMenu(menu);
    }, []);

    // Global keyboard shortcuts for BottomMenu
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            const target = e.target as HTMLElement;
            if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable) return;

            if (e.key === 'b' && !e.metaKey && !e.ctrlKey && !e.altKey) {
                e.preventDefault();
                setActiveMenu(prev => prev === 'blocks' ? null : 'blocks');

            } else if (e.key === 't' && !e.metaKey && !e.ctrlKey && !e.altKey) {
                e.preventDefault();
                setActiveMenu(prev => prev === 'templates' ? null : 'templates');
            } else if (e.key === 'f' && (e.ctrlKey || e.metaKey)) {
                e.preventDefault();
                if (isSearchMode) {
                    setIsSearchMode(false);
                    setSearchQuery('');
                } else {
                    openSearch();
                }
            } else if (e.key === 'j' && (e.ctrlKey || e.metaKey)) {
                e.preventDefault();
                setIsSearchMode(false);
                setAIImageMode(false);
                toggleAIPanel();
            } else if (e.key === 'i' && (e.ctrlKey || e.metaKey)) {
                e.preventDefault();
                setIsSearchMode(false);
                setAIImageMode(true);
                openAIPanel('create');
            } else if (e.key === 'n' && (e.ctrlKey || e.metaKey)) {
                e.preventDefault();
                handleAddNoteRef.current();
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isSearchMode]);

    const activeFilters = useMemo(() => parseSearchQuery(searchQuery), [searchQuery]);

    /* Position-only writes happen every node-drag frame. Subscribing to the
       nodes array made this motion-heavy command island re-render (and re-run
       Motion's layout projection) for every one of them. The tag signature is
       stable through movement; action handlers read the latest node geometry
       imperatively at the moment they run. */
    const allTagsKey = useStore(state => {
        const tags = new Set<string>();
        state.nodes.forEach(node => {
            const nodeTags = 'tags' in node.data ? node.data.tags : undefined;
            if (Array.isArray(nodeTags)) {
                nodeTags.forEach(tag => tags.add(tag));
            }
        });
        return JSON.stringify(Array.from(tags).sort());
    });
    const allTags = useMemo(() => JSON.parse(allTagsKey) as string[], [allTagsKey]);

    const toggleFilter = (key: string, value: string) => {
        const filters = { ...activeFilters };
        if (key === 'tag') {
            if (filters.tags.includes(value)) {
                filters.tags = filters.tags.filter(t => t !== value);
            } else {
                filters.tags.push(value);
            }
        } else {
            const filterRecord = filters as unknown as Record<string, string | undefined>;
            if (filterRecord[key] === value) {
                delete filterRecord[key];
            } else {
                filterRecord[key] = value;
            }
        }

        // Reconstruct query string
        let newQuery = filters.text;
        filters.tags.forEach(t => newQuery += ` #${t}`);
        if (filters.status) newQuery += ` status:${filters.status}`;
        if (filters.priority) newQuery += ` priority:${filters.priority}`;
        if (filters.type) newQuery += ` is:${filters.type}`;
        if (filters.date) newQuery += ` date:${filters.date}`;
        if (filters.startDate) newQuery += ` after:${filters.startDate}`;
        if (filters.endDate) newQuery += ` before:${filters.endDate}`;

        const cleanedQuery = newQuery.trim();
        setSearchQuery(cleanedQuery);
        if (cleanedQuery && !isSearchMode) setIsSearchMode(true);
    };

    const vp = () => {
        const { x, y, zoom } = getViewport();
        return { x, y, zoom, screenW: window.innerWidth, screenH: window.innerHeight };
    };

    /* The overlap-avoidance placement in findNonOverlappingPosition can push a
       new card outside the visible viewport once the screen is crowded. A
       card's block editor only mounts once it's near-viewport (see
       useLazyRender/NoteExpandedContent), so an off-screen card would sit as
       a permanently blank loading skeleton until the user happened to pan
       onto it. Pan to a new card whenever placement landed it out of view,
       so it's always immediately visible and editable. */
    const panIntoViewIfNeeded = (position: { x: number; y: number }, size: { width: number; height: number }) => {
        const { x: vpX, y: vpY, zoom } = getViewport();
        const flowLeft = -vpX / zoom;
        const flowTop = -vpY / zoom;
        const flowRight = flowLeft + window.innerWidth / zoom;
        const flowBottom = flowTop + window.innerHeight / zoom;
        const outOfView = position.x < flowLeft || position.y < flowTop
            || position.x + size.width > flowRight || position.y + size.height > flowBottom;
        if (outOfView) {
            setCenter(position.x + size.width / 2, position.y + size.height / 2, { zoom, duration: 300 });
        }
    };

    const handleAddNote = () => {
        const centerX = window.innerWidth / 2;
        const centerY = window.innerHeight / 2;
        const flowPos = screenToFlowPosition({ x: centerX, y: centerY });

        const NOTE_WIDTH = 432;
        const NOTE_HEIGHT = 432;

        const position = findNonOverlappingPosition(
            flowPos,
            { width: NOTE_WIDTH, height: NOTE_HEIGHT },
            useStore.getState().nodes,
            currentParentId,
            vp(),
        );

        addNode('note', position, { viewMode: 'expanded' }, { width: NOTE_WIDTH, height: NOTE_HEIGHT }, currentParentId || undefined);
        panIntoViewIfNeeded(position, { width: NOTE_WIDTH, height: NOTE_HEIGHT });
    };

    /**
     * Add a board, in one of its two views.
     *
     * One node type, not two: a calendar IS a board — the same cards, read by
     * date instead of by lane — so this differs from the board only in the
     * `viewMode` it opens on, and switching afterwards is a control on the node
     * rather than a different thing to create. See kanbanTypes.ts.
     *
     * Placed and panned to on the same path as every other add in this menu, so
     * a board never lands off-screen or on top of something.
     */
    const handleAddBoard = (view: 'board' | 'calendar') => {
        const isCalendar = view === 'calendar';
        /* The calendar is always exactly four lanes wide whatever the board's
           lane count — see KANBAN_CALENDAR_WIDTH — so the two views seed
           different widths and the node does not jump when you switch. */
        const size = {
            width: isCalendar ? KANBAN_CALENDAR_WIDTH : KANBAN_DEFAULT_WIDTH,
            height: KANBAN_DEFAULT_HEIGHT,
        };
        const flowPos = screenToFlowPosition({ x: window.innerWidth / 2, y: window.innerHeight / 2 });
        const position = findNonOverlappingPosition(
            flowPos,
            size,
            useStore.getState().nodes,
            currentParentId,
            vp(),
        );

        addNode(
            'kanban',
            position,
            isCalendar ? { viewMode: 'calendar' } : undefined,
            size,
            currentParentId || undefined,
        );
        panIntoViewIfNeeded(position, size);
    };
    // Kept in a ref so the global Ctrl+N listener always calls the latest
    // closure without re-subscribing on every render.
    useEffect(() => {
        handleAddNoteRef.current = handleAddNote;
    });

    // The contextual empty state lives with React Flow, while creation logic
    // (placement, collision avoidance and panning) belongs here. A tiny event
    // keeps that CTA on the same proven creation path as the Add button and
    // Ctrl/Cmd+N shortcut.
    useEffect(() => {
        const addFromEmptyState = () => handleAddNoteRef.current();
        window.addEventListener('chnk-it:add-note', addFromEmptyState);
        return () => window.removeEventListener('chnk-it:add-note', addFromEmptyState);
    }, []);

    const handleDragStart = (e: React.DragEvent, type: string, metadata?: Record<string, unknown>) => {
        e.dataTransfer.setData('application/reactflow-block-type', type);

        const blockData = {
            block: {
                id: uuidv4(),
                type: type,
                content: '',
                metadata: metadata
            },
            sourceNodeId: null
        };
        e.dataTransfer.setData('application/chnk-it-block-data', JSON.stringify(blockData));

        if (metadata) {
            e.dataTransfer.setData('application/chnk-it-block-metadata', JSON.stringify(metadata));
        }
        e.dataTransfer.effectAllowed = 'copy';
    };

    // Declared as functions, not consts: the keyboard-navigation effect above
    // calls both, and a const would be in its temporal dead zone there.
    function handleTemplateClick(templateId: string) {
        const template = templates.find(t => t.id === templateId);
        if (!template) return;

        const centerX = window.innerWidth / 2;
        const centerY = window.innerHeight / 2;
        const flowPos = screenToFlowPosition({ x: centerX, y: centerY });
        
        // Use a large size approximation for template to find non-overlapping space
        const position = findNonOverlappingPosition(
            flowPos,
            { width: 1200, height: 1000 },
            useStore.getState().nodes,
            currentParentId,
            vp(),
        );

        const { nodes: newNodes, edges: newEdges } = template.generateNodes(position, currentParentId || null);
        
        useStore.getState().setNodes(prev => [...prev, ...newNodes]);
        if (newEdges.length > 0) {
            useStore.setState((prev: AppState) => ({ edges: [...prev.edges, ...newEdges] }));
        }
    }

    function handleBlockClick(block: typeof MENU_ITEMS[0]) {
        // Columns need their metadata seeded with empty column content, otherwise the
        // node renders as an empty box (matches editor slash-command behaviour).
        const metadata = block.type === 'columns'
            ? {
                columns: Array.from({ length: block.meta?.count || 2 }).map(() => ({
                    id: uuidv4(),
                    content: [{ id: uuidv4(), type: 'text', content: '' }],
                })),
            }
            : block.type === 'gallery'
                ? createGalleryMetadata([], block.meta)
                : block.meta;

        const newBlock = {
            id: uuidv4(),
            type: block.type,
            content: '',
            metadata
        };

        const targetNodeId = centerPanelId || fullscreenId;

        if (targetNodeId) {
            const activeNode = useStore.getState().nodes.find(n => n.id === targetNodeId);
            if (activeNode) {
                const safeContent = getNodeBlocks(activeNode.data) ?? [];
                updateNodeData(targetNodeId, {
                    content: [...safeContent, newBlock]
                });
                return;
            }
        }

        const centerX = window.innerWidth / 2;
        const centerY = window.innerHeight / 2;

        const flowPos = screenToFlowPosition({ x: centerX, y: centerY });

        // Each column needs ~200px to be comfortably editable; scale node width with the
        // number of columns per row (4 columns render as a 2x2 grid, so only 2 per row).
        const columnCount = block.type === 'columns' ? (block.meta?.count || 2) : 0;
        const columnsPerRow = columnCount === 4 ? 2 : columnCount;
        // A table opens at the expanded-card width so its default columns fit —
        // at 300 it shipped with a permanent horizontal scrollbar even empty.
        const BLOCK_WIDTH = block.type === 'columns' ? Math.max(550, columnsPerRow * 220) : block.type === 'gallery' ? GALLERY_NODE_WIDTH : isMediaType(block.type) ? 208 : block.type === 'table' ? MIN_EXPANDED_SIZE : 300;
        const BLOCK_HEIGHT = 100;

        const position = findNonOverlappingPosition(
            flowPos,
            { width: BLOCK_WIDTH, height: BLOCK_HEIGHT },
            useStore.getState().nodes,
            currentParentId,
            vp(),
        );

        addNode('block', position, {
            content: [newBlock],
            isStandaloneBlock: true
        }, { width: BLOCK_WIDTH, height: BLOCK_HEIGHT }, currentParentId || undefined);
    }

    // Handle keyboard navigation inside the open menu
    useEffect(() => {
        if (!activeMenu || highlightedIndex === null) return;

        const columns = activeMenu === 'views' ? 4 : activeMenu === 'templates' ? 4 : 6;
        const totalItems = activeMenu === 'views' ? 4 : activeMenu === 'templates' ? templates.length : MENU_ITEMS.length;

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                setActiveMenu(null);
                e.preventDefault();
                return;
            }

            if (e.key === 'ArrowRight') {
                setHighlightedIndex(prev => (prev === null ? 0 : Math.min(totalItems - 1, prev + 1)));
                e.preventDefault();
            } else if (e.key === 'ArrowLeft') {
                setHighlightedIndex(prev => (prev === null ? 0 : Math.max(0, prev - 1)));
                e.preventDefault();
            } else if (e.key === 'ArrowDown') {
                setHighlightedIndex(prev => (prev === null ? 0 : Math.min(totalItems - 1, prev + columns)));
                e.preventDefault();
            } else if (e.key === 'ArrowUp') {
                setHighlightedIndex(prev => (prev === null ? 0 : Math.max(0, prev - columns)));
                e.preventDefault();
            } else if (e.key === 'Enter') {
                if (activeMenu === 'templates') {
                    const template = templates[highlightedIndex];
                    if (template) {
                        handleTemplateClick(template.id);
                    }
                } else {
                    const block = MENU_ITEMS[highlightedIndex];
                    if (block) {
                        handleBlockClick(block);
                    }
                }
                setActiveMenu(null);
                e.preventDefault();
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => {
            window.removeEventListener('keydown', handleKeyDown);
        };
    }, [activeMenu, highlightedIndex, screenToFlowPosition, addNode, currentParentId]);

    const transitionVariants: Variants = {
        initial: { opacity: 0, scale: 0.95 },
        animate: { opacity: 1, scale: 1, transition: { type: 'spring', stiffness: 400, damping: 32 } },
        exit: { opacity: 0, scale: 0.95, transition: { duration: 0.15, ease: "easeOut" } }
    };

    // The wide states — search and the two selection toolbars — open in the lane
    // beside the rail rather than inside it: a 60px icon column has nowhere to
    // put a 520px field. (AI is a side panel of its own, not a flyout.)
    const flyoutState = isSearchMode ? 'search'
        : hasSelectedEdges ? 'edge'
        : null;
    /* Selection is a mode of the bottom dock, not a second toolbar beside it.
       Removing the idle rail lets the action surface take its exact place and
       Motion can read the change as one continuous command island. */
    const isEdgeSelectionIsland = flyoutState === 'edge';

    /* A node side peek is an editing surface, not a split view. The vertical
       rail that used to appear beside it duplicated controls and crowded the
       reading edge, so it stays fully out of the way until the peek closes. */
    const hasNodeSidePeekOpen = Boolean(rightSidePanelId) || Boolean(leftSidePanelId);

    /* Docking. The menu lives on the bottom edge, always — there is no rail
       mode. It does not need one: this menu is mounted inside `.canvasFrame`
       rather than the shell, and the side panels are in-flow siblings that take
       real width off that frame, so an open panel narrows the box the menu
       centres itself in. It stays on the bottom edge and slides to the middle
       of whatever canvas is left, rather than standing up on its side. */

    if (hasNodeSidePeekOpen) return null;

    return (
        <>
            {/* data-app-menu marks the menu as chrome, not canvas: the side
                panels' click-away handlers skip it, so pressing a rail button
                doesn't close the panel out from under the press. */}
            <div className={`${styles.railLayer} ${styles.dockBottom}`} data-app-menu ref={menuRef}>
            {!isEdgeSelectionIsland && (
            <div className={styles.railRow}>
            <motion.div
                className={styles.sideRail}
                whileHover={{ y: -4 }}
            >
                {/* gap has to live on the column, not on .sideRail: AnimatePresence
                    inserts a wrapper between the rail and its buttons, so the
                    rail's own `gap` never reached them. */}
                <motion.div
                    key="default"
                    variants={transitionVariants}
                    initial="initial"
                    animate="animate"
                    style={{ display: 'flex', flexDirection: 'row', width: 'auto', height: '100%', justifyContent: 'center', alignItems: 'center', gap: 12 }}
                >
                        <button
                            className={styles.iconBtn}
                            onClick={openSearch}
                            title="Search (Ctrl+F)"
                        >
                            <Search size={20} />
                        </button>
                        <div
                            className={styles.blocksWrapper}
                            onMouseEnter={() => {
                                hoverTimeoutRef.current = window.setTimeout(() => {
                                    openMenu('addNoteModes');
                                }, 1000);
                            }}
                            onMouseLeave={() => {
                                if (hoverTimeoutRef.current) {
                                    clearTimeout(hoverTimeoutRef.current);
                                }
                            }}
                        >
                            <FloatingActionButton
                                label="Add new note card"
                                onClick={() => {
                                    if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
                                    handleAddNote();
                                }}
                                title="Add New Note Card (Hover for modes)"
                            >
                                <Plus size={24} color="#fff" />
                            </FloatingActionButton>

                            <div className={`${styles.hoverMenu} ${activeMenu === 'addNoteModes' ? styles.menuVisible : ''}`}>
                                <div className={styles.menuHeader}>
                                    <h3 className={styles.menuTitle}>Card Modes</h3>
                                    <button
                                        className={styles.menuCloseBtn}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            setActiveMenu(null);
                                        }}
                                        title="Close"
                                    >
                                        <X size={12} />
                                    </button>
                                </div>
                                <div className={styles.menuGrid} style={{ gridTemplateColumns: 'repeat(2, 1fr)' }}>
                                    {[
                                        { id: 'expanded', label: 'Expanded', desc: 'Full card view', icon: Square },
                                        { id: 'medium', label: 'Medium', desc: 'Compact view', icon: RectangleHorizontal },
                                        { id: 'icon', label: 'Icon', desc: 'Minimal icon', icon: File },
                                        { id: 'folder', label: 'Folder', desc: 'Cover & icon in a folder', icon: Folder },
                                        { id: 'titleview', label: 'Title Only', desc: 'Just the title', icon: AppWindow }
                                    ].map((mode) => (
                                        <div
                                            key={mode.id}
                                            className={styles.draggableItem}
                                            onClick={() => {
                                                const centerX = window.innerWidth / 2;
                                                const centerY = window.innerHeight / 2;
                                                const flowPos = screenToFlowPosition({ x: centerX, y: centerY });
                                                const isSmall = mode.id === 'icon' || mode.id === 'folder';
                                                const NOTE_WIDTH = isSmall ? 120 : 432;
                                                const NOTE_HEIGHT = isSmall ? 120 : 432;
                                                const position = findNonOverlappingPosition(
                                                    flowPos,
                                                    { width: NOTE_WIDTH, height: NOTE_HEIGHT },
                                                    useStore.getState().nodes,
                                                    currentParentId,
                                                    vp(),
                                                );
                                                addNode('note', position, { viewMode: mode.id, showMetadata: false }, { width: NOTE_WIDTH, height: NOTE_HEIGHT }, currentParentId || undefined);
                                                panIntoViewIfNeeded(position, { width: NOTE_WIDTH, height: NOTE_HEIGHT });
                                                setActiveMenu(null);
                                            }}
                                        >
                                            <div className={styles.itemIconWrapper}>
                                                <mode.icon size={20} />
                                            </div>
                                            <div className={styles.customTooltip}>
                                                <div className={styles.tooltipLabel}>{mode.label}</div>
                                                <div className={styles.tooltipDesc}>{mode.desc}</div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>

                        {/* A board and a calendar are one node type in two views,
                            so they are one button: the click adds the common
                            case and the hover offers the pair — the same bargain
                            the Add-card button already makes with its modes. */}
                        {FEATURES.kanban && (
                        <div
                            className={styles.blocksWrapper}
                            onMouseEnter={() => {
                                hoverTimeoutRef.current = window.setTimeout(() => {
                                    openMenu('boardViews');
                                }, 1000);
                            }}
                            onMouseLeave={() => {
                                if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
                            }}
                        >
                            <button
                                className={`${styles.iconBtn} ${activeMenu === 'boardViews' ? styles.iconBtnActive : ''}`}
                                onClick={() => {
                                    if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
                                    handleAddBoard('board');
                                }}
                                title="Add a board (hover for views)"
                            >
                                <KanbanSquare size={20} />
                            </button>

                            <div className={`${styles.hoverMenu} ${activeMenu === 'boardViews' ? styles.menuVisible : ''}`}>
                                <div className={styles.menuHeader}>
                                    <h3 className={styles.menuTitle}>Plan</h3>
                                    <button
                                        className={styles.menuCloseBtn}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            setActiveMenu(null);
                                        }}
                                        title="Close"
                                    >
                                        <X size={12} />
                                    </button>
                                </div>
                                <div className={styles.menuGrid} style={{ gridTemplateColumns: 'repeat(2, 1fr)' }}>
                                    {[
                                        { id: 'board', label: 'Board', desc: 'Cards in lanes by their metadata', icon: KanbanSquare },
                                        { id: 'calendar', label: 'Calendar', desc: 'The same cards, by date', icon: Calendar },
                                    ].map((view) => (
                                        <div
                                            key={view.id}
                                            className={styles.draggableItem}
                                            onClick={() => {
                                                handleAddBoard(view.id as 'board' | 'calendar');
                                                setActiveMenu(null);
                                            }}
                                        >
                                            <div className={styles.itemIconWrapper}>
                                                <view.icon size={20} />
                                            </div>
                                            <div className={styles.customTooltip}>
                                                <div className={styles.tooltipLabel}>{view.label}</div>
                                                <div className={styles.tooltipDesc}>{view.desc}</div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                        )}

                        <div className={styles.blocksWrapper}>
                            <button
                                className={`${styles.iconBtn} ${activeMenu === 'templates' ? styles.iconBtnActive : ''}`}
                                onClick={() => openMenu(activeMenu === 'templates' ? null : 'templates')}
                                title="Templates"
                                style={{ marginLeft: 8 }}
                            >
                                <LayoutTemplate size={20} />
                            </button>

                            <div className={`${styles.hoverMenu} ${activeMenu === 'templates' ? styles.menuVisible : ''}`}>
                                <div className={styles.menuHeader}>
                                    <h3 className={styles.menuTitle}>Templates</h3>
                                    <button
                                        className={styles.menuCloseBtn}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            setActiveMenu(null);
                                        }}
                                        title="Close"
                                    >
                                        <X size={12} />
                                    </button>
                                </div>
                                <div className={styles.menuGrid} style={{ gridTemplateColumns: 'repeat(4, 1fr)' }}>
                                    {templates.map((template, index) => {
                                        const TemplateIcon = template.icon;
                                        return (
                                        <div
                                            key={template.id}
                                            className={`${styles.draggableItem} ${highlightedIndex === index ? styles.draggableItemHighlighted : ''}`}
                                            onClick={() => {
                                                handleTemplateClick(template.id);
                                                setActiveMenu(null);
                                            }}
                                            onMouseEnter={() => {
                                                if (hoverTimeoutRef.current) window.clearTimeout(hoverTimeoutRef.current);
                                                hoverTimeoutRef.current = window.setTimeout(() => setHoveredTemplateId(template.id), 400);
                                            }}
                                            onMouseLeave={() => {
                                                if (hoverTimeoutRef.current) window.clearTimeout(hoverTimeoutRef.current);
                                                setHoveredTemplateId(null);
                                            }}
                                        >
                                            <div className={styles.itemIconWrapper}>
                                                <TemplateIcon size={20} />
                                            </div>
                                            <div className={styles.customTooltip}>
                                                <div className={styles.tooltipLabel}>{template.name}</div>
                                                <div className={styles.tooltipDesc}>{template.description}</div>
                                            </div>
                                        </div>
                                    )})}
                                </div>
                            </div>
                        </div>

                        <div className={styles.separator} />

                        <div className={styles.blocksWrapper}>
                            <button
                                className={`${styles.iconBtn} ${activeMenu === 'blocks' ? styles.iconBtnActive : ''}`}
                                onClick={() => openMenu(activeMenu === 'blocks' ? null : 'blocks')}
                                title="Browse Blocks"
                            >
                                <LayoutGrid size={20} />
                            </button>

                            <div className={`${styles.hoverMenu} ${activeMenu === 'blocks' ? styles.menuVisible : ''}`}>
                                <div className={styles.menuHeader}>
                                    <h3 className={styles.menuTitle}>Blocks</h3>
                                    <button
                                        className={styles.menuCloseBtn}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            setActiveMenu(null);
                                        }}
                                        title="Close"
                                    >
                                        <X size={12} />
                                    </button>
                                </div>
                                <div className={styles.menuGrid}>
                                    {MENU_ITEMS.map((block, index) => {
                                        const Icon = block.icon;
                                        return (
                                            <div
                                                key={block.label}
                                                className={`${styles.draggableItem} ${highlightedIndex === index ? styles.draggableItemHighlighted : ''}`}
                                                draggable
                                                onDragStart={(e) => handleDragStart(e, block.type, block.meta)}
                                                onClick={() => {
                                                    handleBlockClick(block);
                                                    setActiveMenu(null);
                                                }}
                                            >
                                                <div className={styles.itemIconWrapper}>
                                                    <Icon size={20} />
                                                </div>
                                                <div className={styles.customTooltip}>
                                                    <div className={styles.tooltipLabel}>{block.label}</div>
                                                    <div className={styles.tooltipDesc}>{block.description}</div>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        </div>

                        {/* AI closes the rail rather than floating beside it.
                            It used to have a surface of its own on the grounds
                            that everything else here acts on the canvas while
                            this opens a panel — but that put two toolbars where
                            the user reads one, and the distinction is carried
                            well enough by the separator and by the button's own
                            accent. Search sits in the rail on the same terms. */}
                        <div className={styles.separator} />

                        <button
                            className={`${styles.aiIconBtn} ${isAIPanelOpen ? styles.aiIconBtnActive : ''}`}
                            onClick={toggleAIPanel}
                            title="AI (Ctrl+J)"
                            aria-label="Open AI assistant"
                        >
                            <span className={styles.aiGlyph} aria-hidden="true">
                                <Sparkles size={20} />
                            </span>
                        </button>
                </motion.div>
            </motion.div>
            </div>
            )}

            <AnimatePresence mode="popLayout" initial={false}>
                {flyoutState === 'search' ? (
                    <motion.div key="search" variants={transitionVariants} initial="initial" animate="animate" exit="exit" className={`${styles.flyout} ${styles.searchContainer}`}>
                        <SearchResults
                            query={searchQuery}
                            onClose={() => {
                                setIsSearchMode(false);
                                setSearchQuery('');
                            }}
                        />
                        <Search size={20} className="text-muted-foreground" style={{ opacity: 0.5, marginLeft: 12 }} />
                        <input
                            type="text"
                            className={styles.searchInput}
                            placeholder="Search your notes"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            autoFocus
                        />

                        <button
                            className={`${styles.filterToggleBtn} ${showFilters ? styles.active : ''}`}
                            onClick={() => setShowFilters(!showFilters)}
                            title="Filters"
                        >
                            <Filter size={16} />
                        </button>

                        <button
                            className={styles.closeSearchBtn}
                            onClick={() => {
                                setIsSearchMode(false);
                                setSearchQuery('');
                                setShowFilters(false);
                            }}
                            title="Close Search"
                        >
                            <X size={16} />
                        </button>

                        {showFilters && (
                            <div className={styles.filterPanel}>
                                <div className={styles.filterGroup}>
                                    <label><Tag size={12} /> Tags</label>
                                    <div className={styles.filterChips}>
                                        {allTags.map(tag => (
                                            <span
                                                key={tag}
                                                className={`${styles.filterChip} ${activeFilters.tags.includes(tag.toLowerCase()) ? styles.selected : ''}`}
                                                onClick={() => toggleFilter('tag', tag.toLowerCase())}
                                            >
                                                #{tag}
                                            </span>
                                        ))}
                                        {allTags.length === 0 && <span className={styles.emptyText}>No tags found</span>}
                                    </div>
                                </div>

                                <div className={styles.filterRow}>
                                    <div className={styles.filterGroup}>
                                        <label><CheckCircle size={12} /> Status</label>
                                        <div className={styles.filterChips}>
                                            {['todo', 'in-progress', 'done', 'backlog'].map(s => (
                                                <span
                                                    key={s}
                                                    className={`${styles.filterChip} ${activeFilters.status === s ? styles.selected : ''}`}
                                                    onClick={() => toggleFilter('status', s)}
                                                >
                                                    {s}
                                                </span>
                                            ))}
                                        </div>
                                    </div>

                                    <div className={styles.filterGroup}>
                                        <label><Flag size={12} /> Priority</label>
                                        <div className={styles.filterChips}>
                                            {['low', 'medium', 'high', 'urgent'].map(p => (
                                                <span
                                                    key={p}
                                                    className={`${styles.filterChip} ${activeFilters.priority === p ? styles.selected : ''}`}
                                                    onClick={() => toggleFilter('priority', p)}
                                                >
                                                    {p}
                                                </span>
                                            ))}
                                        </div>
                                    </div>
                                </div>

                                <div className={styles.filterRow}>
                                    <div className={styles.filterGroup}>
                                        <label><Calendar size={12} /> Type</label>
                                        <div className={styles.filterChips}>
                                            {['note', 'block'].map(t => (
                                                <span
                                                    key={t}
                                                    className={`${styles.filterChip} ${activeFilters.type === t ? styles.selected : ''}`}
                                                    onClick={() => toggleFilter('is', t)}
                                                >
                                                    {t}
                                                </span>
                                            ))}
                                        </div>
                                    </div>

                                    <div className={styles.filterGroup}>
                                        <label><Calendar size={12} /> Time</label>
                                        <div className={styles.filterChips}>
                                            <span
                                                className={`${styles.filterChip} ${activeFilters.startDate === new Date().toISOString().split('T')[0] ? styles.selected : ''}`}
                                                onClick={() => toggleFilter('after', new Date().toISOString().split('T')[0])}
                                            >
                                                Today
                                            </span>
                                            <span
                                                className={`${styles.filterChip} ${activeFilters.date?.includes(new Date().toISOString().split('T')[0].substring(0, 7)) ? styles.selected : ''}`}
                                                onClick={() => toggleFilter('date', new Date().toISOString().split('T')[0].substring(0, 7))}
                                            >
                                                This Month
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}
                    </motion.div>
                ) : flyoutState === 'edge' ? (
                    <motion.div layout layoutId="bottom-command-island" key="edge" variants={transitionVariants} initial="initial" animate="animate" exit="exit" className={`${styles.flyout} ${styles.selectionIsland}`}>
                        <EdgeEditingToolbar />
                    </motion.div>
                ) : null}
            </AnimatePresence>

            {/* Keep contextual actions warm while letting a tiny child own the
                selection subscription. Search and edge editing temporarily
                suspend this layer because they occupy the same command lane. */}
            <NodeSelectionToolbarLayer suspended={isSearchMode || hasSelectedEdges} />
            </div>
            
            {/* Modal is rendered outside the menu container */}
            <TemplatePreviewModal
                nodes={hoveredPreview?.nodes || []}
                edges={hoveredPreview?.edges || []}
                name={hoveredTemplate?.name}
                description={hoveredTemplate?.description}
                isVisible={hoveredTemplateId !== null}
            />
        </>
    );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { useStore } from '../../store/useStore';
import { getNodeById } from '../../store/nodeIndex';
import { FolderArt } from '../card/FolderArt';
import { CardIcon } from '../card/iconMap';
import { ChevronDown, ChevronRight, Columns2, Flag, PanelLeftClose, PanelLeftOpen, Plus, Search } from '../../components/icons';
import type { AppNode, BlockNode, NoteNode } from '../../types';
import { FileArt, describeFile, isFileNode, nodeFileBlock } from '../file';
import { formatBytes } from '../editor/mediaTypes';
import type { FullscreenPane } from './FullscreenModal';
import styles from './FullscreenNoteList.module.css';

/**
 * The note stream down the left of fullscreen.
 *
 * Fullscreen used to be a dead end: one card, and the only way to the next one
 * was back out to the canvas. The rail lists the cards of the canvas fullscreen
 * was entered from so reading can move card to card without ever leaving it —
 * the reason it starts from that canvas rather than the whole graph is that
 * "the canvas you came from" is the set the user already has in mind.
 *
 * A card that holds nested cards carries them as a collapsed branch. Nesting is
 * real structure here — a `page` block in a note's body is a child node whose
 * `parentId` points back at the note — so the tree is read straight off
 * `parentId` rather than being a second index that could drift out of sync.
 *
 * Each row wears the folder view of its card: the same artwork the canvas draws
 * for a folder-mode card, so a card is recognised in the rail by the picture it
 * already has, not by a generic list bullet. Collapsed, the rail keeps the same
 * list as a strip of card icons — narrow enough to stay out of the way, but
 * still navigable, which a rail collapsing to nothing would not be.
 */

/**
 * What the rail lists: the canvas's cards, and its files.
 *
 * A file is a `block` node holding one `file` block, so it has none of the
 * fields a note keeps — no `createdAt`, no icon, no description. Rather than
 * teach every reader below about two shapes, the accessors under this comment
 * answer the same handful of questions for both, and the rest of the rail is
 * written against them.
 */
type RailNode = NoteNode | BlockNode;

const isRailNode = (node: AppNode): node is RailNode =>
    node.type === 'note' || isFileNode(node);

const isNoteRow = (node: RailNode): node is NoteNode => node.type === 'note';

const railLabel = (node: RailNode): string => {
    if (isNoteRow(node)) return node.data.label || 'Untitled';
    return nodeFileBlock(node)?.metadata?.name || 'File';
};

/** A note's own subtitle; for a file, what it is and how big. */
const railDescription = (node: RailNode): string | undefined => {
    if (isNoteRow(node)) return node.data.description;
    const block = nodeFileBlock(node);
    if (!block) return undefined;
    const kind = describeFile(block.metadata?.type, block.metadata?.name);
    const size = block.metadata?.size;
    return typeof size === 'number' ? `${kind.label} · ${formatBytes(size)}` : kind.label;
};

const railColor = (node: RailNode): string | undefined => node.data.color;

const railIsPinned = (node: RailNode): boolean => Boolean(node.data.isPinned);

/** Glyph for the collapsed strip, where there is no room for the artwork. */
const railIcon = (node: RailNode): string => {
    if (isNoteRow(node)) return node.data.icon ?? 'FileText';
    const block = nodeFileBlock(node);
    return describeFile(block?.metadata?.type, block?.metadata?.name).icon;
};

/** ISO timestamps, from wherever each kind of node keeps them. */
const railCreatedAt = (node: RailNode): string | undefined =>
    isNoteRow(node) ? node.data.createdAt : nodeFileBlock(node)?.metadata?.addedAt;

const railUpdatedAt = (node: RailNode): string | undefined =>
    isNoteRow(node) ? node.data.updatedAt : nodeFileBlock(node)?.metadata?.addedAt;

/** Gap left under the lowest sibling when a new card is dropped on the canvas. */
const NEW_CARD_GAP = 48;
const DEFAULT_CARD_HEIGHT = 432;

/**
 * Indent stops growing past this depth. Nesting itself stays unlimited — the
 * rail is 288px wide, so past three levels the indent would be taking width
 * from the labels to say something the branch lines already say.
 */
const INDENT_CAP = 3;

/** Belt-and-braces stop: a corrupt `parentId` cycle must not hang the render. */
const MAX_TREE_DEPTH = 20;

type TreeRow = {
    node: RailNode;
    depth: number;
    hasChildren: boolean;
};

type DateGroupId = 'today' | 'yesterday' | 'this-week' | 'older';
type SortMode = 'created' | 'updated' | 'title' | 'manual';

const DATE_GROUPS: ReadonlyArray<{ id: DateGroupId; label: string }> = [
    { id: 'today', label: 'Today' },
    { id: 'yesterday', label: 'Yesterday' },
    { id: 'this-week', label: 'This Week' },
    { id: 'older', label: 'Older' },
];

const creationTime = (node: RailNode) => {
    const value = Date.parse(railCreatedAt(node) ?? '');
    return Number.isFinite(value) ? value : 0;
};

const updatedTime = (node: RailNode) => {
    const value = Date.parse(railUpdatedAt(node) ?? '');
    return Number.isFinite(value) ? value : 0;
};

/** Body copy belongs to the same local search as a node's visible metadata.
 *  A file has no body to search — its name and kind are all there is. */
const searchableText = (node: RailNode) => {
    if (!isNoteRow(node)) {
        return `${railLabel(node)} ${railDescription(node) ?? ''}`.toLocaleLowerCase();
    }
    const { label = '', description = '', content } = node.data;
    const body = typeof content === 'string' ? content : JSON.stringify(content ?? '');
    return `${label} ${description} ${body}`.toLocaleLowerCase();
};

function creationGroup(node: RailNode, now = new Date()): DateGroupId {
    const createdAt = creationTime(node);
    if (!createdAt) return 'older';

    const today = new Date(now);
    today.setHours(0, 0, 0, 0);
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);
    const weekStart = new Date(today);
    weekStart.setDate(weekStart.getDate() - ((weekStart.getDay() + 6) % 7));

    if (createdAt >= today.getTime()) return 'today';
    if (createdAt >= yesterday.getTime()) return 'yesterday';
    if (createdAt >= weekStart.getTime()) return 'this-week';
    return 'older';
}

export function FullscreenNoteList({
    leftId,
    rightId,
    focusedPane,
    onSelect,
    onOpenSplit
}: {
    leftId: string;
    /** The second pane's card, or null when a single note is open. */
    rightId: string | null;
    focusedPane: FullscreenPane;
    /** Open a card in whichever pane the reader last touched. */
    onSelect: (id: string) => void;
    /** Open a card beside the current one, splitting the view. */
    onOpenSplit: (id: string) => void;
}) {
    /* The whole array, filtered in a memo rather than inside the selector:
       a selector that builds a new array re-runs on every store write and
       fails zustand's identity check, re-rendering the rail constantly. */
    const nodes = useStore(s => s.nodes);
    const activeNode = useStore(s => getNodeById(s.nodes, leftId));
    const addNode = useStore(s => s.addNode);
    const updateNodeData = useStore(s => s.updateNodeData);
    const isSplit = rightId !== null;
    const [query, setQuery] = useState('');
    const [sortMode, setSortMode] = useState<SortMode>('created');
    const searchRef = useRef<HTMLInputElement | null>(null);

    /* Two notes side by side leave little room to read in, so a split folds the
       rail down to its icons and a single note opens it again. That is the
       default, not a lock: the override below holds whatever the reader last
       chose, and is tagged with the split state it was chosen under so that
       entering or leaving a split falls back to the default rather than
       carrying a decision made about a different layout. */
    const [override, setOverride] = useState<{ split: boolean; collapsed: boolean } | null>(null);
    const collapsed = override && override.split === isSplit ? override.collapsed : isSplit;
    const setCollapsed = (value: boolean) => setOverride({ split: isSplit, collapsed: value });

    /**
     * The canvas the tree is rooted at, fixed for as long as fullscreen is open.
     *
     * Deliberately not derived from the open card: opening a nested child would
     * then re-root the rail to that child's own level, and the branch the reader
     * had just expanded to find it would vanish underneath them. Pinning the
     * root means opening a child only moves the highlight. The rail unmounts
     * with the modal, so the next fullscreen re-pins from wherever it opens.
     */
    const rootRef = useRef<{ value: string | null } | null>(null);
    if (rootRef.current === null) {
        rootRef.current = { value: activeNode?.parentId ?? null };
    }
    const rootParentId = rootRef.current.value;

    /* One pass over the nodes, bucketed by parent — the tree is walked several
       times below (rows, totals) and re-scanning the array for each level would
       make the rail O(nodes × levels). */
    const childrenByParent = useMemo(() => {
        const map = new Map<string | null, RailNode[]>();
        for (const node of nodes) {
            if (!isRailNode(node)) continue;
            const key = node.parentId ?? null;
            const bucket = map.get(key);
            if (bucket) bucket.push(node);
            else map.set(key, [node]);
        }
        /* Every order falls back to canvas position, keeping legacy cards
           stable even when they predate timestamps. */
        for (const bucket of map.values()) {
            bucket.sort((a, b) => {
                if (sortMode === 'title') {
                    const byTitle = railLabel(a).localeCompare(railLabel(b), undefined, { sensitivity: 'base' });
                    if (byTitle) return byTitle;
                } else if (sortMode === 'created') {
                    const byCreated = creationTime(b) - creationTime(a);
                    if (byCreated) return byCreated;
                } else if (sortMode === 'updated') {
                    const byUpdated = updatedTime(b) - updatedTime(a);
                    if (byUpdated) return byUpdated;
                }
                return (a.position.y - b.position.y) || (a.position.x - b.position.x);
            });
        }
        return map;
    }, [nodes, sortMode]);

    const topLevel = useMemo(
        () => childrenByParent.get(rootParentId) ?? [],
        [childrenByParent, rootParentId]
    );

    /** Every branch between the root and a card that is currently on screen. */
    const revealed = useMemo(() => {
        const set = new Set<string>();
        for (const openId of [leftId, rightId]) {
            if (!openId) continue;
            let cursor = getNodeById(nodes, openId)?.parentId ?? null;
            let guard = 0;
            while (cursor && cursor !== rootParentId && guard++ < MAX_TREE_DEPTH) {
                set.add(cursor);
                cursor = getNodeById(nodes, cursor)?.parentId ?? null;
            }
        }
        return set;
    }, [nodes, leftId, rightId, rootParentId]);

    /* Expansion is an override *on top of* `revealed` rather than the whole
       truth, so the path down to whatever is open unfolds itself and the reader
       still keeps the last word on any branch they touch. */
    const [expandOverrides, setExpandOverrides] = useState<Record<string, boolean>>({});

    const isExpanded = useCallback(
        (id: string) => expandOverrides[id] ?? revealed.has(id),
        [expandOverrides, revealed]
    );

    const toggleExpanded = useCallback((id: string) => {
        setExpandOverrides(prev => ({ ...prev, [id]: !(prev[id] ?? revealed.has(id)) }));
    }, [revealed]);

    /* Opening a card has to show it, so any collapse the reader had set on the
       way down to it is dropped — `revealed` then takes over for that path. */
    const revealPath = useCallback((id: string) => {
        setExpandOverrides(prev => {
            let next = prev;
            let cursor = getNodeById(nodes, id)?.parentId ?? null;
            let guard = 0;
            while (cursor && cursor !== rootParentId && guard++ < MAX_TREE_DEPTH) {
                if (next[cursor] === false) {
                    if (next === prev) next = { ...prev };
                    delete next[cursor];
                }
                cursor = getNodeById(nodes, cursor)?.parentId ?? null;
            }
            return next;
        });
    }, [nodes, rootParentId]);

    const handleSelect = useCallback((id: string) => {
        revealPath(id);
        onSelect(id);
    }, [revealPath, onSelect]);

    const handleOpenSplit = useCallback((id: string) => {
        revealPath(id);
        onOpenSplit(id);
    }, [revealPath, onOpenSplit]);

    const togglePinned = useCallback((node: RailNode) => {
        updateNodeData(node.id, { isPinned: !railIsPinned(node) });
    }, [updateNodeData]);

    /**
     * Top-level cards are grouped by creation date; their visible descendants
     * stay with that parent, preserving the tree rather than scattering child
     * notes into a different time bucket from the branch they belong to.
     */
    const dateSections = useMemo(() => {
        const groups = new Map<DateGroupId, TreeRow[]>();
        for (const group of DATE_GROUPS) groups.set(group.id, []);

        const normalizedQuery = query.trim().toLocaleLowerCase();
        const branchMatches = (node: RailNode, depth: number): boolean => {
            if (depth > MAX_TREE_DEPTH) return false;
            if (searchableText(node).includes(normalizedQuery)) return true;
            return (childrenByParent.get(node.id) ?? []).some(child => branchMatches(child, depth + 1));
        };

        const appendBranch = (node: RailNode, depth: number, out: TreeRow[]) => {
            if (depth > MAX_TREE_DEPTH) return;
            const children = childrenByParent.get(node.id) ?? [];
            if (normalizedQuery && !branchMatches(node, depth)) return;
            const hasChildren = children.length > 0;
            out.push({ node, depth, hasChildren });
            /* Search reveals matching paths without changing the reader's own
               expansion choices, which come back intact when it is cleared. */
            if (hasChildren && (normalizedQuery || isExpanded(node.id))) {
                for (const child of children) appendBranch(child, depth + 1, out);
            }
        };

        const now = new Date();
        for (const node of childrenByParent.get(rootParentId) ?? []) {
            appendBranch(node, 0, groups.get(creationGroup(node, now))!);
        }

        const datedSections = DATE_GROUPS
            .map((group) => ({ ...group, rows: groups.get(group.id)! }))
            .filter((group) => group.rows.length > 0);

        return sortMode === 'created'
            ? datedSections
            : datedSections.length > 0 ? [{ id: 'all', label: 'Notes', rows: datedSections.flatMap(section => section.rows) }] : [];
    }, [childrenByParent, rootParentId, isExpanded, query, sortMode]);

    /** The collapsed icon rail keeps this exact filtered and sorted order. */
    const rows = useMemo(() => dateSections.flatMap((section) => section.rows), [dateSections]);
    const pinnedRows = useMemo(() => rows.filter(({ node }) => railIsPinned(node)), [rows]);
    const unpinnedSections = useMemo(() => dateSections.map(section => ({
        ...section,
        rows: section.rows.filter(({ node }) => !railIsPinned(node)),
    })).filter(section => section.rows.length > 0), [dateSections]);

    /* The header counts the whole tree, not the visible rows — a number that
       shrank every time a branch was folded would be reporting the furniture
       rather than the notes. */
    const totalNotes = useMemo(() => {
        let count = 0;
        const walk = (parentId: string | null, depth: number) => {
            if (depth > MAX_TREE_DEPTH) return;
            for (const node of childrenByParent.get(parentId) ?? []) {
                count++;
                walk(node.id, depth + 1);
            }
        };
        walk(rootParentId, 0);
        return count;
    }, [childrenByParent, rootParentId]);

    /**
     * A card made here is a canvas card like any other — the rail only decides
     * where it lands. It joins the rail's own canvas (never the branch being
     * read, which could be collapsed and hide it), under the lowest card there
     * rather than at the origin, so going back to the canvas finds it at the
     * foot of the column instead of stacked on whatever already sits at 0,0.
     */
    const handleCreate = useCallback(() => {
        const anchors: AppNode[] = topLevel.length > 0 ? topLevel : (activeNode ? [activeNode] : []);

        const position = anchors.length > 0
            ? {
                x: Math.min(...anchors.map(n => n.position.x)),
                y: Math.max(...anchors.map(n =>
                    n.position.y + (typeof n.style?.height === 'number' ? n.style.height : DEFAULT_CARD_HEIGHT)
                )) + NEW_CARD_GAP
            }
            : { x: 0, y: 0 };

        const newId = uuidv4();
        addNode('note', position, { label: 'New Note' }, undefined, rootParentId ?? undefined, newId);

        /* addNode declines silently when a beta creation limit is hit — it puts
           up its own notice — so the card is only opened once it really exists. */
        if (useStore.getState().nodes.some(n => n.id === newId)) {
            onSelect(newId);
        }
    }, [topLevel, activeNode, rootParentId, addNode, onSelect]);

    /** Which pane a row is showing in, or null when it is not open at all. */
    const paneOf = (id: string): FullscreenPane | null =>
        id === leftId ? 'left' : (id === rightId ? 'right' : null);

    const focusedRef = useRef<HTMLButtonElement | null>(null);

    const renderRow = (node: RailNode, depth: number, hasChildren: boolean) => {
        const label = railLabel(node);
        const description = railDescription(node);
        const color = railColor(node);
        const pinned = railIsPinned(node);
        const file = nodeFileBlock(node);
        const pane = paneOf(node.id);
        const isFocused = pane === focusedPane;
        const expanded = hasChildren && isExpanded(node.id);

        return (
            <div
                key={node.id}
                className={`${styles.row} ${depth > 0 ? styles.rowNested : ''}`}
                style={{ '--depth': Math.min(depth, INDENT_CAP) } as React.CSSProperties}
            >
                {hasChildren && (
                    <button
                        className={`${styles.chevron} ${expanded ? styles.chevronOpen : ''}`}
                        onClick={() => toggleExpanded(node.id)}
                        title={expanded ? 'Collapse' : 'Expand'}
                        aria-label={`${expanded ? 'Collapse' : 'Expand'} ${label || 'Untitled'}`}
                        aria-expanded={expanded}
                    >
                        <ChevronRight size={13} />
                    </button>
                )}

                <button
                    ref={isFocused ? focusedRef : undefined}
                    className={`${styles.item} ${pane ? styles.itemOpen : ''} ${pane === 'left' ? styles.paneLeft : pane === 'right' ? styles.paneRight : ''} ${isFocused ? styles.itemActive : ''}`}
                    onClick={() => handleSelect(node.id)}
                    aria-current={isFocused ? 'true' : undefined}
                    style={color ? ({ '--node-accent': color } as React.CSSProperties) : undefined}
                    data-accented={color ? '' : undefined}
                >
                    {/* Each row wears its object's own artwork: a card shows the
                        folder the canvas draws for it, a file shows its sheet.
                        Recognising a row by the picture it already has is the
                        whole point of the rail, and a file is no exception. */}
                    <span className={styles.art}>
                        {file
                            ? <FileArt name={file.metadata?.name} mime={file.metadata?.type} poster={file.metadata?.poster} size={46} />
                            : isNoteRow(node)
                                ? <FolderArt coverImage={node.data.coverImage} icon={node.data.icon} size={46} />
                                : null}
                    </span>
                    <span className={styles.text}>
                        <span className={styles.label}>{label}</span>
                        {description && <span className={styles.description}>{description}</span>}
                    </span>
                    {isSplit && pane && <span className={styles.side}>{pane === 'left' ? 'L' : 'R'}</span>}
                </button>

                {!pane && (
                    <button className={`${styles.splitButton} icon-hover`} onClick={() => handleOpenSplit(node.id)} title="Open beside" aria-label={`Open ${label || 'Untitled'} beside`}>
                        <Columns2 size={14} />
                    </button>
                )}

                <button
                    className={`${styles.pinButton} ${pinned ? styles.pinButtonActive : ''}`}
                    onClick={() => togglePinned(node)}
                    title={pinned ? 'Unpin' : 'Pin'}
                    aria-label={`${pinned ? 'Unpin' : 'Pin'} ${label}`}
                >
                    <Flag size={13} />
                </button>
            </div>
        );
    };

    // Keep the open card visible when fullscreen is entered on an off-screen row.
    useEffect(() => {
        focusedRef.current?.scrollIntoView({ block: 'nearest' });
    }, [leftId, rightId, focusedPane, collapsed]);

    useEffect(() => {
        const isTypingTarget = (target: EventTarget | null) => target instanceof HTMLElement && (
            target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable
        );
        const onKeyDown = (event: KeyboardEvent) => {
            if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') {
                event.preventDefault();
                setCollapsed(false);
                requestAnimationFrame(() => searchRef.current?.focus());
                return;
            }
            if (isTypingTarget(event.target) || event.metaKey || event.ctrlKey || event.altKey) return;
            if (event.key !== 'ArrowUp' && event.key !== 'ArrowDown') return;
            const currentId = focusedPane === 'left' ? leftId : rightId;
            const currentIndex = rows.findIndex(({ node }) => node.id === currentId);
            const nextIndex = event.key === 'ArrowUp'
                ? Math.max(0, currentIndex - 1)
                : Math.min(rows.length - 1, currentIndex + 1);
            const next = rows[nextIndex];
            if (!next || next.node.id === currentId) return;
            event.preventDefault();
            handleSelect(next.node.id);
        };
        document.addEventListener('keydown', onKeyDown);
        return () => document.removeEventListener('keydown', onKeyDown);
    }, [leftId, rightId, focusedPane, rows, handleSelect]);

    if (collapsed) {
        return (
            <div className={styles.rail}>
                <button
                    className={`${styles.toggle} icon-hover`}
                    onClick={() => setCollapsed(false)}
                    title="Show notes"
                    aria-label="Show notes"
                >
                    <PanelLeftOpen size={16} />
                </button>

                <button
                    className={`${styles.toggle} icon-hover`}
                    onClick={handleCreate}
                    title="New note"
                    aria-label="New note"
                >
                    <Plus size={16} />
                </button>

                <div className={styles.railDivider} />

                {/* The same rows as the open rail, minus the indent — 52px has no
                    room to draw depth, and the strip's job here is reach, not
                    structure. Branches on the way to an open card are unfolded
                    by `revealed`, so a nested card being read still appears. */}
                <div className={styles.railList}>
                    {rows.map(({ node }) => {
                        const pane = paneOf(node.id);
                        const isFocused = pane === focusedPane;
                        const label = railLabel(node);
                        const color = railColor(node);

                        return (
                            <button
                                key={node.id}
                                ref={isFocused ? focusedRef : undefined}
                                className={`${styles.railItem} ${pane ? styles.railItemOpen : ''} ${pane === 'left' ? styles.paneLeft : pane === 'right' ? styles.paneRight : ''} ${isFocused ? styles.railItemActive : ''}`}
                                onClick={() => handleSelect(node.id)}
                                title={isSplit && pane ? `${label} — open ${pane}` : label}
                                aria-label={label}
                                aria-current={isFocused ? 'true' : undefined}
                                style={color ? ({ '--node-accent': color } as React.CSSProperties) : undefined}
                                data-accented={color ? '' : undefined}
                            >
                                <CardIcon icon={railIcon(node)} size={18} />
                                {isSplit && pane && (
                                    <span className={styles.railSide}>{pane === 'left' ? 'L' : 'R'}</span>
                                )}
                            </button>
                        );
                    })}
                </div>
            </div>
        );
    }

    return (
        <aside className={styles.panel} aria-label="Notes on this canvas">
            <div className={styles.header}>
                <span className={styles.headerTitle}>
                    Notes
                    <span className={styles.count}>{totalNotes}</span>
                </span>
                <div className={styles.headerActions}>
                    <button
                        className={`${styles.toggle} icon-hover`}
                        onClick={handleCreate}
                        title="New note"
                        aria-label="New note"
                    >
                        <Plus size={16} />
                    </button>
                    <button
                        className={`${styles.toggle} icon-hover`}
                        onClick={() => setCollapsed(true)}
                        title="Hide notes"
                        aria-label="Hide notes"
                    >
                        <PanelLeftClose size={16} />
                    </button>
                </div>
            </div>

            <div className={styles.tools}>
                <label className={styles.search}>
                    <Search size={14} aria-hidden="true" />
                    <input
                        ref={searchRef}
                        type="search"
                        value={query}
                        onChange={(event) => setQuery(event.target.value)}
                        placeholder="Search notes"
                        aria-label="Search notes"
                    />
                    <kbd>⌘/Ctrl K</kbd>
                </label>
                <label className={styles.sort}>
                    <select value={sortMode} onChange={(event) => setSortMode(event.target.value as SortMode)} aria-label="Sort notes">
                        <option value="created">Created</option>
                        <option value="updated">Updated</option>
                        <option value="title">Title</option>
                        <option value="manual">Canvas order</option>
                    </select>
                    <ChevronDown size={13} aria-hidden="true" />
                </label>
            </div>

            <div className={styles.list}>
                {rows.length === 0 && (
                    <p className={styles.empty}>{query ? 'No notes match this search.' : 'No other notes on this canvas.'}</p>
                )}

                {pinnedRows.length > 0 && (
                    <section className={`${styles.dateGroup} ${styles.pinnedGroup}`} aria-labelledby="pinned-notes">
                        <h2 className={styles.dateHeading} id="pinned-notes">Pinned</h2>
                        {pinnedRows.map(({ node, depth, hasChildren }) => renderRow(node, depth, hasChildren))}
                    </section>
                )}

                {unpinnedSections.map((section) => (
                    <section className={styles.dateGroup} key={section.id} aria-labelledby={`note-date-${section.id}`}>
                        <h2 className={styles.dateHeading} id={`note-date-${section.id}`}>{section.label}</h2>
                        {section.rows.map(({ node, depth, hasChildren }) => renderRow(node, depth, hasChildren))}
                    </section>
                ))}
            </div>
        </aside>
    );
}
